# --------------------------------------------------------------------------- #
# MPFB access
# --------------------------------------------------------------------------- #
def mpfb_module():
    for name in ("bl_ext.user_default.mpfb", "bl_ext.blender_org.mpfb", "mpfb"):
        try:
            importlib.import_module(name + ".services.humanservice")
            return name
        except Exception:
            continue
    raise RuntimeError("MPFB add-on not found/enabled. Install it from extensions.blender.org "
                       "(Edit > Preferences > Get Extensions > MPFB).")


def group_points(obj, group_name):
    idx = obj.vertex_groups[group_name].index
    return [obj.matrix_world @ v.co for v in obj.data.vertices
            if any(g.group == idx and g.weight > 0.0 for g in v.groups)]


def bbox_centre(points):
    lo = Vector((min(p.x for p in points), min(p.y for p in points), min(p.z for p in points)))
    hi = Vector((max(p.x for p in points), max(p.y for p in points), max(p.z for p in points)))
    return (lo + hi) * 0.5


def snap_axis(v, tol_deg=6.0):
    """Snap a detected direction to the nearest world axis when within tolerance."""
    v = v.normalized()
    best = max(range(3), key=lambda i: abs(v[i]))
    axis = Vector((0, 0, 0))
    axis[best] = 1.0 if v[best] > 0 else -1.0
    if math.degrees(v.angle(axis)) <= tol_deg:
        return axis, True
    return v, False


def helper_sphere(meas_side, forward):
    """Centre and radius of the model's own (oversized) eye helper sphere."""
    joint = meas_side["joint"]
    pts = meas_side["helper"]
    box = bbox_centre(pts)
    # lateral position from the helper's bounding box, depth from the model's eye joint
    centre = box + forward * (joint - box).dot(forward)
    # radius = mean distance of the helper's equatorial ring from the axis
    ring = [((p - centre) - forward * (p - centre).dot(forward)).length
            for p in pts if abs((p - centre).dot(forward)) < 0.003]
    if not ring:
        ring = [((p - centre) - forward * (p - centre).dot(forward)).length for p in pts]
        return centre, max(ring)
    return centre, sum(ring) / len(ring)


def smoothstep(e0, e1, x):
    t = max(0.0, min(1.0, (x - e0) / (e1 - e0)))
    return t * t * (3 - 2 * t)


class Aperture:
    """Outline of one lid opening seen from the front, in globe-centred face coordinates:
    x along image-right, z along up (metres)."""

    def __init__(self, cols):
        self.xs = [c[0] for c in cols]
        k = 3

        def smooth_list(vals):
            out = []
            for i in range(len(vals)):
                win = vals[max(0, i - k):i + k + 1]
                out.append(sum(win) / len(win))
            return out

        self.lo = smooth_list([c[1] for c in cols])
        self.hi = smooth_list([c[2] for c in cols])
        self.x_min, self.x_max = self.xs[0], self.xs[-1]
        self.corner_min = (self.x_min, 0.5 * (self.lo[0] + self.hi[0]))
        self.corner_max = (self.x_max, 0.5 * (self.lo[-1] + self.hi[-1]))

    def margins(self, x):
        """(z_lower, z_upper) of the lid margins at lateral position x."""
        if x <= self.x_min:
            return self.corner_min[1], self.corner_min[1]
        if x >= self.x_max:
            return self.corner_max[1], self.corner_max[1]
        f = (x - self.x_min) / (self.x_max - self.x_min) * (len(self.xs) - 1)
        i = min(int(f), len(self.xs) - 2)
        t = f - i
        return self.lo[i] * (1 - t) + self.lo[i + 1] * t, self.hi[i] * (1 - t) + self.hi[i + 1] * t

    def outside_distance(self, x, z):
        """0 inside the opening, otherwise roughly how far (x, z) is outside its outline."""
        if x < self.x_min:
            return math.hypot(x - self.corner_min[0], z - self.corner_min[1])
        if x > self.x_max:
            return math.hypot(x - self.corner_max[0], z - self.corner_max[1])
        zl, zu = self.margins(x)
        if z > zu:
            return z - zu
        if z < zl:
            return zl - z
        return 0.0

    def corner_fade(self, x):
        """1 in the middle of the opening, falling to 0 at the corners."""
        if x >= 0:
            return 1.0 - smoothstep(0.50, 1.05, x / self.x_max)
        return 1.0 - smoothstep(0.50, 1.05, x / self.x_min)


def aperture_map(human, joint, forward, up, right):
    """Ray-cast the lid opening from the front on a grid.

    Returns [(x, z_lo, z_hi), ...] for each open grid column, x along `right` and z along
    `up`, in metres relative to the eye joint.
    """
    dg = bpy.context.evaluated_depsgraph_get()
    ev = human.evaluated_get(dg)
    mw = human.matrix_world
    inv = mw.inverted()
    d_local = (inv.to_3x3() @ (-forward)).normalized()
    step = APERTURE_STEP
    nx, nz = int(0.019 / step), int(0.013 / step)
    open_cells = set()
    for ix in range(-nx, nx + 1):
        for iz in range(-nz, nz + 1):
            origin = joint + forward * 0.08 + right * (ix * step) + up * (iz * step)
            hit, loc, _n, _f = ev.ray_cast(inv @ origin, d_local)
            if (not hit) or (mw @ loc - joint).dot(forward) < 0.002:
                open_cells.add((ix, iz))
    if not open_cells:
        raise RuntimeError("could not find the lid opening by ray casting")
    seed = min(open_cells, key=lambda c: c[0] ** 2 + c[1] ** 2)
    region = {seed}
    stack = [seed]
    while stack:
        cx, cz = stack.pop()
        for nb in ((cx + 1, cz), (cx - 1, cz), (cx, cz + 1), (cx, cz - 1)):
            if nb in open_cells and nb not in region:
                region.add(nb)
                stack.append(nb)
    cols = {}
    for ix, iz in region:
        lo, hi = cols.get(ix, (iz, iz))
        cols[ix] = (min(lo, iz), max(hi, iz))
    keys = sorted(cols)
    out = []
    prev = cols[keys[0]]
    for ix in range(keys[0], keys[-1] + 1):
        prev = cols.get(ix, prev)
        out.append((ix * step, (prev[0] - 0.5) * step, (prev[1] + 0.5) * step))
    return out


def cornea_geometry():
    """(shell radius, limbus half-angle, cornea-sphere centre offset) of the outer eye surface."""
    rs = EYE_RADIUS + SHELL_GAP
    limbus = math.asin(IRIS_RADIUS / rs)
    z_c = rs * math.cos(limbus) - math.sqrt(CORNEA_CURVATURE ** 2 - IRIS_RADIUS ** 2)
    return rs, limbus, z_c


def shell_radius(alpha):
    """Distance from the globe centre to the outer eye surface, `alpha` radians off the optical
    axis (includes the corneal bulge)."""
    rs, limbus, z_c = cornea_geometry()
    if alpha >= limbus:
        return rs
    return z_c * math.cos(alpha) + math.sqrt(CORNEA_CURVATURE ** 2 - (z_c * math.sin(alpha)) ** 2)


def aperture_samples(ap, n=24):
    """Lid opening (rest pose) sampled for the calibration record: lateral x and the lower /
    upper margin heights, globe-centred face coordinates in metres."""
    xs = [ap.x_min + (ap.x_max - ap.x_min) * i / (n - 1) for i in range(n)]
    lo, hi = zip(*[ap.margins(x) for x in xs])
    return {"x": xs, "lo": list(lo), "hi": list(hi)}


def extend_inner_corners(human, meas, forward, up, amount, outer_pull=0.0):
    """Move each inner eye corner `amount` metres toward the nose, lengthening the lid opening.

    A smooth lateral displacement of the skin, centred on the corner found by ray casting
    (Gaussian falloff, sigma 5.5 mm): the corner tip moves by the full amount, the lid margins
    over the iris hardly at all. The outline changes; depth is fitted afterwards as usual."""
    if amount <= 0 and outer_pull <= 0:
        return
    right = up.cross(forward).normalized()
    mw = human.matrix_world
    inv = mw.inverted()
    body = human.vertex_groups["body"].index
    sigma = 0.0055
    plans = []
    for side in ("L", "R"):
        joint = meas[side]["joint"]
        other = meas["R" if side == "L" else "L"]["joint"]
        nose = -1.0 if (joint - other).dot(right) > 0 else 1.0
        cols = aperture_map(human, joint, forward, up, right)
        inner = cols[0] if nose < 0 else cols[-1]
        outer = cols[-1] if nose < 0 else cols[0]
        plans.append((joint, nose * amount, inner[0], 0.5 * (inner[1] + inner[2])))
        plans.append((joint, nose * outer_pull, outer[0], 0.5 * (outer[1] + outer[2])))
    moved = 0
    for v in human.data.vertices:
        if not any(g.group == body for g in v.groups):
            continue
        p = mw @ v.co
        shift = 0.0
        for joint, move, xc, zc in plans:
            q = p - joint
            if q.dot(forward) < -0.006 or move == 0.0:
                continue
            d2 = (q.dot(right) - xc) ** 2 + (q.dot(up) - zc) ** 2
            if d2 < (4 * sigma) ** 2:
                shift += move * math.exp(-d2 / (sigma * sigma))
        if abs(shift) > 1e-7:
            v.co = inv @ (p + right * shift)
            moved += 1
    human.data.update()
    bpy.context.view_layer.update()
    log("inner corners moved %.1f mm and outer corners %.1f mm toward the nose (%d vertices)"
        % (amount * 1e3, outer_pull * 1e3, moved))


def seat_eyes(human, meas, forward, up):
    """Choose each 25 mm globe's centre and measure its lid opening.

    Lateral position: the model's eye joint (keeps the IPD).  Vertical: placed in the lid
    opening (measured by ray casting) so the lids frame the iris naturally.  Depth: the globe
    surface meets the model's helper surface at LID_CONTACT_RADIUS from the axis, where the
    upper and lower lid margins sit.

    Returns (centres, apertures); apertures are in globe-centred face coordinates.
    """
    right = up.cross(forward).normalized()
    maps = {}
    spans = []
    for side in ("L", "R"):
        cols = aperture_map(human, meas[side]["joint"], forward, up, right)
        maps[side] = cols
        mid_col = min(cols, key=lambda c: abs(c[0]))
        spans.append((mid_col[1], mid_col[2]))
        log("eye", side, "lid opening: width %.1f mm, height on the midline %.1f mm"
            % ((cols[-1][0] - cols[0][0]) * 1e3, (mid_col[2] - mid_col[1]) * 1e3))
    # same vertical offset for both eyes (keeps the eyes level)
    lo = sum(sp[0] for sp in spans) / len(spans)
    hi = sum(sp[1] for sp in spans) / len(spans)
    # lower lid margin just overlaps the lower limbus; the upper lid then covers the top of
    # the iris slightly, as in a relaxed adult eye
    v_off = lo + min(IRIS_RADIUS - LOWER_LID_OVERLAP, 0.54 * (hi - lo))
    centres = {}
    apertures = {}
    for side in ("L", "R"):
        joint, r_h = helper_sphere(meas[side], forward)
        rho = LID_CONTACT_RADIUS
        depth = math.sqrt(r_h ** 2 - rho ** 2) - math.sqrt(EYE_RADIUS ** 2 - rho ** 2)
        other = meas["R" if side == "L" else "L"]["joint"]
        temporal = 1.0 if (meas[side]["joint"] - other).dot(right) > 0 else -1.0
        shift = temporal * GLOBE_TEMPORAL_SHIFT
        centres[side] = joint + right * shift + up * v_off + forward * depth
        lateral = (meas[side]["joint"] - joint).dot(right) - shift   # map is joint-centred
        apertures[side] = Aperture([(x + lateral, zl - v_off, zh - v_off) for x, zl, zh in maps[side]])
        ap = apertures[side]
        nasal_extent = -ap.x_min if temporal > 0 else ap.x_max
        temporal_extent = (ap.x_max - ap.x_min) - nasal_extent
        log("eye", side, "iris sits at %.3f of the lid opening from the inner corner (opening %.1f mm); "
            "outer corner at %.2f of the globe radius" % (nasal_extent / (ap.x_max - ap.x_min), (ap.x_max - ap.x_min) * 1e3,
                                                         temporal_extent / EYE_RADIUS))
        log("eye", side, "helper radius %.2f mm; centre = joint %+.2f mm up, %+.2f mm forward"
            % (r_h * 1e3, v_off * 1e3, depth * 1e3))
    return centres, apertures


def fit_lids_to_globes(human, meas, centres, apertures, forward, up):
    """Make the lid skin hug the 25 mm globes.

    MakeHuman sculpts the lids around a ~33 mm helper sphere. Away from the optical axis a
    realistic globe curves away faster, which would leave a dark gap at the eye corners.
    Pass 1 moves each skin vertex near the lid opening back along -F by the depth difference
    between the helper surface and the globe surface at its position; the move fades out
    within LID_FIT_FALLOFF of the lid outline so the cheek and brow keep their shape. Only
    depth changes, so the outline of the opening seen from the front is untouched.
    Pass 2 lifts any lid vertex that would touch the corneal bulge in the reset pose.
    """
    mw = human.matrix_world
    inv = mw.inverted()
    right = up.cross(forward).normalized()
    body = human.vertex_groups["body"].index
    body_verts = [v for v in human.data.vertices if any(g.group == body for g in v.groups)]
    mid = (centres["L"] + centres["R"]) * 0.5
    moved = 0
    biggest = 0.0
    lifted = 0
    for side in ("L", "R"):
        c_h, r_h = helper_sphere(meas[side], forward)
        c_g = centres[side]
        ap = apertures[side]
        cap = EYE_RADIUS * CORNER_CAP
        nose = -1.0 if (c_g - mid).dot(right) > 0 else 1.0
        nasal_extent = -ap.x_min if nose < 0 else ap.x_max
        for v in body_verts:
            p = mw @ v.co
            rel_h = p - c_h
            if rel_h.dot(forward) < -0.002 or rel_h.length > r_h + 0.02:
                continue
            rho_h = (rel_h - forward * rel_h.dot(forward)).length
            rel_g = p - c_g
            rho_g = (rel_g - forward * rel_g.dot(forward)).length
            if rho_h >= r_h:
                front_h = c_h.dot(forward)
            else:
                front_h = c_h.dot(forward) + math.sqrt(r_h ** 2 - rho_h ** 2)
            temporal = nose * rel_g.dot(right) < 0.0              # on the temple side of this eye
            cap_v = EYE_RADIUS * CORNER_CAP_OUTER if temporal else cap
            front_g = c_g.dot(forward) + math.sqrt(EYE_RADIUS ** 2 - min(rho_g, cap_v) ** 2)
            delta = max(0.0, front_h - front_g - LID_CLEARANCE)
            shell = rel_h.length - r_h                       # distance outside the helper surface
            outside = ap.outside_distance(rel_g.dot(right), rel_g.dot(up))
            fade = (1.0 - smoothstep(0.002, 0.012, shell)) * (1.0 - smoothstep(LID_FIT_FULL, LID_FIT_FALLOFF, outside))
            # the medial canthus sits in front of the globe's edge (the caruncle fills the space
            # between): relieve the push progressively toward the inner corner
            xn = nose * rel_g.dot(right)
            fade *= 1.0 - INNER_CORNER_RELIEF * smoothstep(0.50 * nasal_extent, 1.05 * nasal_extent, xn)
            d = delta * fade
            if d > 1e-6:
                v.co = inv @ (p - forward * d)
                moved += 1
                biggest = max(biggest, d)
        axis = (mid + forward * FIXATION_DISTANCE_M - c_g).normalized()
        for v in body_verts:
            q = mw @ v.co - c_g
            r = q.length
            if q.dot(forward) <= 0.0 or r < EYE_RADIUS - 0.0004 or r > EYE_RADIUS + 0.003:
                continue
            need = shell_radius(q.angle(axis)) + LID_CLEARANCE
            if r < need:
                v.co = inv @ (c_g + q * (need / r))
                lifted += 1
    human.data.update()
    bpy.context.view_layer.update()
    log("lid fit: moved %d vertices (max %.2f mm), lifted %d clear of the cornea" % (moved, biggest * 1e3, lifted))


# --------------------------------------------------------------------------- #
# Lids that follow the gaze, blink, and the wet details of the eye
# --------------------------------------------------------------------------- #
def add_shape_key(obj, name, field):
    """Add a shape key whose vertices are field(world_position) (None = unchanged)."""
    if obj.data.shape_keys is None:
        obj.shape_key_add(name="Basis")
    basis = obj.data.shape_keys.key_blocks[0].data
    kb = obj.shape_key_add(name=name, from_mix=False)
    mw = obj.matrix_world
    inv = mw.inverted()
    n = 0
    for i in range(len(obj.data.vertices)):
        q = field(mw @ basis[i].co)
        if q is not None:
            kb.data[i].co = inv @ q
            n += 1
    kb.value = 0.0
    return n


def lid_field(centre, ap, forward, up, angle_fn, gaze_axis, rigid, closure=0.0, brow_gap=None):
    """Deformation field for one eye's lids: rotate about the eye's horizontal axis through the
    globe centre by angle_fn(x, is_upper) radians (+ = up), weighted so the lid margin moves
    fully and the surrounding skin progressively less. `rigid` objects (lashes, tear line)
    move with the margin without the skin falloff.

    closure > 0 marks a blink key (0..1 of full closure): the upper lid then moves as thin
    skin over a static brow (BLINK_* constants), and lid tissue that ends up over the globe
    keeps a thin, constant height above the eye surface (cornea included), so the closed lid
    drapes over the globe instead of rotating down as a thick block."""
    right = up.cross(forward).normalized()

    def eye_surface(v):
        return shell_radius(v.angle(gaze_axis)) if v.length > 1e-9 else EYE_RADIUS

    def field(p):
        q = p - centre
        x = q.dot(right)
        z = q.dot(up)
        if q.dot(forward) < -0.006 or x * x + z * z > 0.038 ** 2:
            return None
        zl, zu = ap.margins(x)
        upper = z >= 0.5 * (zl + zu)
        if rigid:
            w = 1.0
        elif closure > 0.0 and upper:
            top = brow_gap(x) if brow_gap is not None else BLINK_BROW
            w = 1.0 - smoothstep(BLINK_PRETARSAL, top, z - zu)          # even stretch, brow static
        elif closure > 0.0:
            w = 1.0 - smoothstep(0.0, BLINK_LOWER_SKIN, zl - z)
        elif upper:
            # gaze follow: the pretarsal strip (margin up to the crease) follows the eye; above
            # it the movement fades out and is zero at the brow, so looking down never drags the
            # brow or forehead (the old 14 mm falloff moved the brow skin over the brow hairs'
            # roots and buried them)
            top = brow_gap(x) if brow_gap is not None else BLINK_BROW
            w = 1.0 - smoothstep(GAZE_PRETARSAL, top, z - zu)
        else:
            w = 1.0 - smoothstep(0.0, LID_SKIN_LOWER, zl - z)
        ang = angle_fn(x, upper) * w
        if abs(ang) < 1e-6:
            return None
        q2 = Matrix.Rotation(-ang, 3, right) @ q           # -ang about `right` lifts the front
        if closure > 0.0 and q.dot(forward) > 0.0:
            # height above the eye surface, before and after the slide
            h = q.length - eye_surface(q)
            if rigid:
                h2 = h                                     # lashes, rims: ride with the margin
            else:
                a, b = BLINK_THICK_A, BLINK_THICK_B
                hc = h if h <= a else a + (b - a) * math.tanh((h - a) / (b - a))
                h2 = h + (hc - h) * min(1.0, w * closure)
            if h > -0.0004:
                r2 = eye_surface(q2) + h2
                q2 = q2 * (r2 / q2.length)
        if not rigid and q.length > EYE_RADIUS - 0.0004:
            need = shell_radius(q2.angle(gaze_axis)) + LID_CLEARANCE
            if q2.length < need:
                q2 = q2 * (need / q2.length)
        return centre + q2
    return field


def add_eyelid_mask(human, centres, apertures, forward, up):
    """Float vertex attribute "eyelid": 1 on the thin lid skin (upper lid up to just above the
    crease, lower lid a few mm below the margin, the margins themselves), fading to 0 toward
    the brow and cheek. The skin shader uses it for thinner-looking skin."""
    right = up.cross(forward).normalized()
    me = human.data
    attr = me.attributes.get("eyelid") or me.attributes.new("eyelid", "FLOAT", "POINT")
    mw = human.matrix_world
    vals = [0.0] * len(me.vertices)
    for side in ("L", "R"):
        c, ap = centres[side], apertures[side]
        for i, v in enumerate(me.vertices):
            q = mw @ v.co - c
            if q.dot(forward) < 0.0:
                continue
            x, z = q.dot(right), q.dot(up)
            if abs(x) > 0.025 or abs(z) > 0.025:
                continue
            xc = min(max(x, ap.x_min), ap.x_max)
            zl, zu = ap.margins(xc)
            lat = 1.0 - smoothstep(0.0, 0.004, abs(x - xc))
            if z >= zu:
                m = 1.0 - smoothstep(BLINK_PRETARSAL + 0.0015, BLINK_BROW - 0.0005, z - zu)
            elif z <= zl:
                m = 1.0 - smoothstep(0.0015, 0.0055, zl - z)
            else:
                m = 1.0
            vals[i] = max(vals[i], m * lat)
    attr.data.foreach_set("value", vals)
    log("eyelid mask: %d vertices > 0.5" % sum(1 for a in vals if a > 0.5))


def brow_gap_fn(brows, centre, ap, forward, up):
    """x -> height above the upper lid margin where the brow (card or hairs) begins, minus a
    small margin: the blink stops moving skin there, so the brow never slides."""
    import numpy as np
    right = up.cross(forward).normalized()
    step, half = 0.0005, 0.016
    nb = int(2 * half / step) + 1
    low = np.full(nb, np.inf)
    dg = bpy.context.evaluated_depsgraph_get()
    for ob in brows:
        ev = ob.evaluated_get(dg)
        me = ev.to_mesh()
        mw = ev.matrix_world
        for v in me.vertices:
            q = mw @ v.co - centre
            if q.dot(forward) < 0.0:
                continue
            i = int(round((q.dot(right) + half) / step))
            if 0 <= i < nb:
                low[i] = min(low[i], q.dot(up))
        ev.to_mesh_clear()
    xs = [-half + i * step for i in range(nb)]
    gaps = []
    for x, zb in zip(xs, low):
        zu = ap.margins(min(max(x, ap.x_min), ap.x_max))[1]
        g = (zb - zu - 0.0005) if np.isfinite(zb) else BLINK_BROW
        gaps.append(min(max(g, BLINK_PRETARSAL + 0.0025), BLINK_BROW))
    k = 5                                                    # smooth along the brow
    sm = [sum(gaps[max(0, i - k):i + k + 1]) / len(gaps[max(0, i - k):i + k + 1]) for i in range(nb)]
    log("brow gap above the lid margin: %.1f .. %.1f mm" % (min(sm) * 1e3, max(sm) * 1e3))

    def fn(x):
        f = (x + half) / step
        i = min(max(int(f), 0), nb - 2)
        t = min(max(f - i, 0.0), 1.0)
        return sm[i] * (1 - t) + sm[i + 1] * t
    return fn


def add_lid_keys(skin_objs, rigid_objs, centres, apertures, forward, up, brows=()):
    """Shape keys: lid_gaze_up / lid_gaze_down (lids follow vertical gaze) and
    lid_blink_1..3 (one third, two thirds and full closure)."""
    right = up.cross(forward).normalized()
    mid = (centres["L"] + centres["R"]) * 0.5
    gaps = {side: brow_gap_fn(brows, centres[side], apertures[side], forward, up) if brows else None
            for side in ("L", "R")}

    def gaze_axis(side, v):
        target = mid + forward * FIXATION_DISTANCE_M + up * (0.05 * v)
        return (target - centres[side]).normalized()

    def follow(ap, upper_deg, lower_deg):
        return lambda x, upper: ap.corner_fade(x) * math.radians(upper_deg if upper else lower_deg)

    def margin_radius(side):
        """Measured radius of the circle (about the eye's horizontal axis) on which the upper and
        lower lid margins travel, per column of the opening: ray cast onto the rendered skin
        just outside each margin. Returns x -> (rho_upper, rho_lower)."""
        ap, c = apertures[side], centres[side]
        skin = _bvh_of(skin_objs[0])
        cols = []
        for x in ap.xs:
            zl, zu = ap.margins(x)
            radii = []
            for z, sgn in ((zu, 1.0), (zl, -1.0)):
                r = None
                for k in range(8):                       # step outward until the skin is hit
                    zz = z + sgn * (0.00025 + 0.00025 * k)
                    hit = skin.ray_cast(c + right * x + up * zz + forward * 0.05, -forward, 0.1)
                    if hit[0] is not None and (hit[0] - c).dot(forward) > 0.0:
                        q = hit[0] - c
                        r = math.hypot(q.dot(forward), z)
                        break
                if r is None:
                    r = math.sqrt(max(EYE_RADIUS ** 2 - x * x, BLINK_MIN_RADIUS ** 2))
                radii.append(r)
            cols.append(radii)
        k = 2
        sm = [[sum(cc[j] for cc in cols[max(0, i - k):i + k + 1]) / len(cols[max(0, i - k):i + k + 1])
               for j in (0, 1)] for i in range(len(cols))]
        log("lid margin radius %s: upper %.1f..%.1f mm, lower %.1f..%.1f mm" % (
            side, min(a[0] for a in sm) * 1e3, max(a[0] for a in sm) * 1e3,
            min(a[1] for a in sm) * 1e3, max(a[1] for a in sm) * 1e3))
        xs = ap.xs

        def fn(x):
            f = (x - xs[0]) / (xs[-1] - xs[0]) * (len(xs) - 1)
            i = min(max(int(f), 0), len(xs) - 2)
            t = min(max(f - i, 0.0), 1.0)
            return (sm[i][0] * (1 - t) + sm[i + 1][0] * t, sm[i][1] * (1 - t) + sm[i + 1][1] * t)
        return fn

    radius_fns = {side: margin_radius(side) for side in ("L", "R")}

    def blink(ap, fraction):
        side = "L" if ap is apertures["L"] else "R"
        rad = radius_fns[side]

        def fn(x, upper):
            # beyond the corners the closure of the last column fades out smoothly (a hard
            # stop there tore the skin into a dark vertical crease at the outer corner)
            fade = 1.0
            if x > ap.x_max:
                fade = 1.0 - smoothstep(ap.x_max, ap.x_max + BLINK_CORNER_FADE, x)
            elif x < ap.x_min:
                fade = 1.0 - smoothstep(-ap.x_min, -ap.x_min + BLINK_CORNER_FADE, -x)
            if fade <= 0.0:
                return 0.0
            x = min(max(x, ap.xs[1]), ap.xs[-2])
            zl, zu = ap.margins(x)
            if zu - zl <= 1e-5:
                return 0.0
            zm = zl + 0.10 * (zu - zl)                       # the lids meet low, as in a real blink
            # the margin travels on a circle of its MEASURED radius at this x (an assumed globe
            # radius vanished at the corners and swung the corner lashes through 90 deg)
            rho = rad(x)[0 if upper else 1]
            rho = max(rho, BLINK_MIN_RADIUS * 0.5, 1.05 * max(abs(zu), abs(zl), abs(zm) + BLINK_OVERLAP))
            if upper:
                zt = zm - BLINK_OVERLAP           # lids press together: no slit seen from the side
                return -fade * fraction * (math.asin(zu / rho) - math.asin(max(-1.0, zt / rho)))
            return fade * fraction * (math.asin(zm / rho) - math.asin(zl / rho))
        return fn

    specs = [("lid_gaze_up", lambda ap: follow(ap, LID_UP_UPPER, LID_UP_LOWER), 1.0, 0.0),
             ("lid_gaze_down", lambda ap: follow(ap, LID_DOWN_UPPER, LID_DOWN_LOWER), -1.0, 0.0),
             ("lid_blink_1", lambda ap: blink(ap, 1.0 / 3.0), 0.0, 1.0 / 3.0),
             ("lid_blink_2", lambda ap: blink(ap, 2.0 / 3.0), 0.0, 2.0 / 3.0),
             ("lid_blink_3", lambda ap: blink(ap, 1.0), 0.0, 1.0)]
    for name, make, v, closure in specs:
        for obj, rigid in [(o, False) for o in skin_objs] + [(o, True) for o in rigid_objs]:
            fields = [lid_field(centres[side], apertures[side], forward, up, make(apertures[side]),
                                gaze_axis(side, v), rigid, closure, gaps[side]) for side in ("L", "R")]

            def both(p, fields=fields):
                for f in fields:
                    q = f(p)
                    if q is not None:
                        return q
                return None
            n = add_shape_key(obj, name, both)
        log("shape key", name, "added")
    return [s[0] for s in specs]


def tube_mesh(name, points, radius, ref, segments=8):
    """A thin tube through `points`, tapered at both ends."""
    mesh = bpy.data.meshes.new(name)
    bm = bmesh.new()
    rings = []
    count = len(points)
    for i, p in enumerate(points):
        t = (points[min(i + 1, count - 1)] - points[max(i - 1, 0)]).normalized()
        n = t.cross(ref).normalized()
        b = t.cross(n).normalized()
        r = radius * min(1.0, 0.2 + i / 5.0, 0.2 + (count - 1 - i) / 5.0)
        rings.append([bm.verts.new(p + (n * math.cos(2 * math.pi * k / segments) + b * math.sin(2 * math.pi * k / segments)) * r)
                      for k in range(segments)])
    for i in range(count - 1):
        for k in range(segments):
            k2 = (k + 1) % segments
            f = bm.faces.new((rings[i][k], rings[i + 1][k], rings[i + 1][k2], rings[i][k2]))
            f.smooth = True
    bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    bm.to_mesh(mesh)
    bm.free()
    return mesh


def caruncle_material(name, centre_rgb, edge_rgb, max_alpha, soft=0.40, coat=0.22, roughness=0.55,
                      coat_roughness=0.08, bump_strength=0.25, bump_distance=0.00003, lobule_scale=3500.0):
    """Moist pink tissue whose colour pales and whose opacity fades toward the patch edge
    (vertex attribute "fade": 1 in the middle, 0 at the rim) so it melts into the corner.
    Colours are LINEAR (Blender's base colour), not sRGB screen values: linear 0.70 shows as
    sRGB 0.85. lobule_scale / bump_* set the small lumps that break a wet highlight into specks."""
    m = bpy.data.materials.new(name)
    nt, out = nodes_reset(m)
    attr = nt.nodes.new("ShaderNodeAttribute")
    attr.attribute_name = "fade"
    ramp = nt.nodes.new("ShaderNodeMapRange")
    ramp.interpolation_type = "SMOOTHSTEP"
    ramp.inputs["From Min"].default_value = 0.0
    ramp.inputs["From Max"].default_value = soft      # opaque except near the rim (low fade)
    ramp.inputs["To Max"].default_value = max_alpha
    nt.links.new(attr.outputs["Fac"], ramp.inputs["Value"])
    mix = nt.nodes.new("ShaderNodeMix")
    mix.data_type = "RGBA"
    mix.inputs[6].default_value = tuple(edge_rgb) + (1.0,)
    mix.inputs[7].default_value = tuple(centre_rgb) + (1.0,)
    nt.links.new(attr.outputs["Fac"], mix.inputs[0])
    b = nt.nodes.new("ShaderNodeBsdfPrincipled")
    nt.links.new(mix.outputs[2], b.inputs["Base Color"])
    nt.links.new(ramp.outputs["Result"], b.inputs["Alpha"])
    b.inputs["Roughness"].default_value = roughness
    b.inputs["Subsurface Weight"].default_value = 0.6
    b.inputs["Subsurface Radius"].default_value = (1.0, 0.3, 0.2)
    b.inputs["Subsurface Scale"].default_value = 0.0012
    b.inputs["Coat Weight"].default_value = coat
    b.inputs["Coat Roughness"].default_value = coat_roughness
    tc = nt.nodes.new("ShaderNodeTexCoord")
    vor = nt.nodes.new("ShaderNodeTexVoronoi")
    vor.inputs["Scale"].default_value = lobule_scale
    nt.links.new(tc.outputs["Object"], vor.inputs["Vector"])
    bump = nt.nodes.new("ShaderNodeBump")
    bump.inputs["Strength"].default_value = bump_strength
    bump.inputs["Distance"].default_value = bump_distance
    nt.links.new(vor.outputs["Distance"], bump.inputs["Height"])
    nt.links.new(bump.outputs["Normal"], b.inputs["Normal"])
    nt.links.new(b.outputs["BSDF"], out.inputs["Surface"])
    return m


def shell_patch(name, fn, nu=26, nt=22):
    """A thin patch draped over the outer eye shell, in globe-centred face coordinates
    (x = image-right, y = up, z = forward). fn(u, t) -> (x, z, height, fade) for u in [0, 1]
    and t in [-1, 1]; the vertex sits `height` above the shell along the globe normal.
    Vertex attribute "fade" drives colour and opacity in the shader."""
    rs = EYE_RADIUS + SHELL_GAP + 0.00002
    mesh = bpy.data.meshes.new(name)
    bm = bmesh.new()
    fade_layer = bm.verts.layers.float.new("fade")
    verts = {}
    for i in range(nu + 1):
        for j in range(nt + 1):
            x, z, h, fade, depth = fn(i / nu, 2.0 * j / nt - 1.0)
            if depth is not None:            # explicit depth (metres in front of the globe centre)
                v = bm.verts.new(Vector((x, z, depth + h)))
                v[fade_layer] = fade
                verts[i, j] = v
                continue
            # beyond the globe's edge the patch carries on at constant depth: the real inner
            # corner (lacus lacrimalis) lies medial to the eyeball, not on it
            cap = CORNER_CAP * rs
            rho = math.hypot(x, z)
            if rho <= cap:
                d = Vector((x, z, math.sqrt(rs * rs - rho * rho))).normalized()
                v = bm.verts.new(d * (rs + h))
            else:
                v = bm.verts.new(Vector((x, z, math.sqrt(rs * rs - cap * cap) + h)))
            v[fade_layer] = fade
            verts[i, j] = v
    for i in range(nu):
        for j in range(nt):
            f = bm.faces.new((verts[i, j], verts[i + 1, j], verts[i + 1, j + 1], verts[i, j + 1]))
            f.smooth = True
    bm.normal_update()
    if sum(f.normal.dot(f.calc_center_median()) for f in bm.faces) < 0:
        bmesh.ops.reverse_faces(bm, faces=bm.faces)      # normals point away from the globe
    bm.to_mesh(mesh)                                     # "fade" becomes a point attribute
    bm.free()
    return mesh


def corner_patch_fn(ap, tip_x, nose, u0, u1, under, height, lumpy, both_ends=False, tip_depth=None):
    """Patch filling the lid opening between lateral distances u0..u1 (metres) from the
    inner-corner tip, spanning the full height between the lid margins plus `under` metres
    tucked beneath each lid. Relief and fade fall to zero at the edge facing the eye."""
    from mathutils import noise

    def fn(u, t):
        # rounded rim: the middle of the patch reaches further toward the eye than its
        # top and bottom, as the caruncle and plica do
        dist = u0 + (u1 - u0) * u * (1.0 - 0.38 * t * t)
        x = tip_x - nose * dist
        zl, zu = ap.margins(x)
        zm, half = 0.5 * (zl + zu), 0.5 * (zu - zl) + under
        z = zm + t * half
        edge = u * u                                     # 0 at the corner, 1 at the eye-side rim
        h = height * math.sin(math.pi * min(1.0, 0.5 + 0.5 * u / 0.3) if u < 0.3 else math.pi * 0.5 * (1.0 + (u - 0.3) / 0.7)) * (1.0 - t * t) ** 1.2
        if lumpy:
            h *= 1.0 + lumpy * noise.noise(Vector((dist * 1400.0, z * 1400.0, 0.37)))
        if both_ends:
            fade = math.sin(math.pi * u) ** 2 * (1.0 - abs(t) ** 6)
        else:
            fade = (1.0 - smoothstep(0.30, 1.0, u)) * (1.0 - abs(t) ** 6)
        depth = None
        if tip_depth is not None:
            # caruncle mound: at lid level in the corner tip, sloping down onto the globe
            rs = EYE_RADIUS + SHELL_GAP + 0.00002
            cap = CORNER_CAP * rs
            rho = min(math.hypot(x, z), cap)
            on_globe = math.sqrt(rs * rs - rho * rho)
            # one smooth dome: highest a third of the way in, tucked under the lid at the tip
            dome = math.sin(math.pi * min(1.0, (u + 0.35) / 1.35)) ** 1.5
            lift = CARUNCLE_FILL * max(0.0, tip_depth - on_globe) * dome * (1.0 - 0.25 * t * t)
            depth = on_globe + lift
        return x, z, max(h, 0.0), fade, depth
    return fn


def groom_lashes(centres, apertures, forward, up):
    """Shorten the lash cards toward their roots on the lid margin (lower lashes much more:
    real lower lashes are short and sparse) and give the lower ones a fainter material."""
    right = up.cross(forward).normalized()
    rs = EYE_RADIUS + SHELL_GAP
    for o in [o for o in bpy.data.objects if o.type == "MESH" and "eyelash" in o.name.lower()]:
        mw = o.matrix_world
        inv = mw.inverted()
        me = o.data
        lower_faces = set()
        for v in me.vertices:
            p = mw @ v.co
            side = min(centres, key=lambda k: (p - centres[k]).length)
            c = centres[side]
            q = p - c
            x, z = q.dot(right), q.dot(up)
            zl, zu = apertures[side].margins(x)
            lower = z < 0.5 * (zl + zu)
            zm = zl if lower else zu
            root = c + right * x + up * zm + forward * math.sqrt(max(rs * rs - x * x - zm * zm, 1e-8))
            sc = LOWER_LASH_SCALE if lower else UPPER_LASH_SCALE
            v.co = inv @ (root + (p - root) * sc)
            v.select = lower
        if len(me.materials) == 1:
            low = me.materials[0].copy()
            low.name = me.materials[0].name + ".lower"
            nt = low.node_tree
            bsdf = next(n for n in nt.nodes if n.type == "BSDF_PRINCIPLED")
            link = bsdf.inputs["Alpha"].links[0] if bsdf.inputs["Alpha"].links else None
            mul = nt.nodes.new("ShaderNodeMath")
            mul.operation = "MULTIPLY"
            mul.inputs[1].default_value = 0.6
            if link:
                nt.links.new(link.from_socket, mul.inputs[0])
            else:
                mul.inputs[0].default_value = bsdf.inputs["Alpha"].default_value
            nt.links.new(mul.outputs[0], bsdf.inputs["Alpha"])
            me.materials.append(low)
            for poly in me.polygons:
                if all(me.vertices[i].select for i in poly.vertices):
                    poly.material_index = 1
        me.update()
    log("lashes groomed (upper x%.2f, lower x%.2f)" % (UPPER_LASH_SCALE, LOWER_LASH_SCALE))


# --------------------------------------------------------------------------- #
# Strand hair: eyelashes and eyebrows
# --------------------------------------------------------------------------- #
# The camera never moves, so each hair is a thin tapered ribbon whose width always faces the
# camera: it renders like a round fibre from this viewpoint at a fraction of the cost of real
# curves, and as a mesh it can carry the same lid-follow / blink shape keys as the lids.

class Ribbons:
    def __init__(self, cam_pos):
        self.cam = cam_pos
        self.verts = []
        self.faces = []
        self.mats = []

    def add(self, pts, r_root, r_tip, mat=0):
        n = len(pts)
        base = len(self.verts)
        for i, p in enumerate(pts):
            t = (pts[min(i + 1, n - 1)] - pts[max(i - 1, 0)]).normalized()
            side = t.cross((self.cam - p).normalized())
            if side.length < 1e-9:
                side = t.orthogonal()
            side.normalize()
            f = i / (n - 1)
            r = r_root * (1 - f) + r_tip * f
            self.verts.append(p - side * r)
            self.verts.append(p + side * r)
        for i in range(n - 1):
            a = base + 2 * i
            self.faces.append((a, a + 1, a + 3, a + 2))
            self.mats.append(mat)

    def to_object(self, name, material):
        me = bpy.data.meshes.new(name)
        me.from_pydata(self.verts, [], self.faces)
        me.update()
        for poly, mi in zip(me.polygons, self.mats):
            poly.use_smooth = True
            poly.material_index = mi
        for m in (material if isinstance(material, (list, tuple)) else [material]):
            me.materials.append(m)
        ob = bpy.data.objects.new(name, me)
        bpy.context.scene.collection.objects.link(ob)
        return ob


def hair_material(name, rgb, roughness, coat=0.0, sss=0.25, spec=0.5):
    m = bpy.data.materials.new(name)
    nt, out = nodes_reset(m)
    b = nt.nodes.new("ShaderNodeBsdfPrincipled")
    b.inputs["Base Color"].default_value = tuple(rgb) + (1.0,)
    b.inputs["Roughness"].default_value = roughness
    b.inputs["Specular IOR Level"].default_value = spec
    b.inputs["Coat Weight"].default_value = coat
    b.inputs["Coat Roughness"].default_value = 0.25
    # a little light passes through a fibre this thin
    b.inputs["Subsurface Weight"].default_value = sss
    b.inputs["Subsurface Radius"].default_value = (1.0, 0.5, 0.25)
    b.inputs["Subsurface Scale"].default_value = 0.00005
    nt.links.new(b.outputs["BSDF"], out.inputs["Surface"])
    return m


def _bvh_of(obj):
    """BVH of the object's surface exactly as it RENDERS (subdivision at render level)."""
    from mathutils.bvhtree import BVHTree
    saved = []
    for m in obj.modifiers:
        if m.type == "SUBSURF" and m.levels != m.render_levels:
            saved.append((m, m.levels))
            m.levels = m.render_levels
    bpy.context.view_layer.update()
    dg = bpy.context.evaluated_depsgraph_get()
    ev = obj.evaluated_get(dg)
    me = ev.to_mesh()
    mw = ev.matrix_world
    verts = [mw @ v.co for v in me.vertices]
    polys = [list(p.vertices) for p in me.polygons]
    ev.to_mesh_clear()
    for m, lv in saved:
        m.levels = lv
    bpy.context.view_layer.update()
    return BVHTree.FromPolygons(verts, polys)


def build_lash_strands(human, centres, apertures, forward, up, cam_pos):
    """Individual eyelashes rooted on the anterior lid margin, curling away from the eye."""
    import random
    rng = random.Random(1234)
    right = up.cross(forward).normalized()
    mid = (centres["L"] + centres["R"]) * 0.5
    skin = _bvh_of(human)
    rib = Ribbons(cam_pos)
    strands = []
    counts = {"upper": LASH_COUNT_UPPER, "lower": LASH_COUNT_LOWER}
    made = 0
    for side in ("L", "R"):
        c = centres[side]
        ap = apertures[side]
        outward = 1.0 if (c - mid).dot(right) > 0 else -1.0       # toward the temple along `right`
        for lid in ("upper", "lower"):
            sgn = 1.0 if lid == "upper" else -1.0
            n = counts[lid]
            x_a, x_b = ap.x_min + 0.0012, ap.x_max - 0.0012
            for k in range(n):
                f = (k + rng.uniform(-0.4, 0.4)) / (n - 1)
                f = min(max(f, 0.0), 1.0)
                x = x_a + (x_b - x_a) * f
                zl, zu = ap.margins(x)
                zm = zu if lid == "upper" else zl
                # root: the lid edge exactly as the camera sees it. March outward from inside
                # the opening until a ray from the front first meets the lid skin.
                edge = None
                for i in range(60):
                    probe = c + right * x + up * (zm + sgn * (-0.0004 + 0.00005 * i))
                    hit = skin.ray_cast(probe + forward * 0.05, -forward, 0.1)
                    if hit[0] is not None and (hit[0] - c).dot(forward) > EYE_RADIUS * 0.3:
                        edge = hit
                        break
                if edge is None:
                    continue
                loc, nrm = edge[0], edge[1].normalized()
                # 2-3 rows of follicles step back across the thickness of the lid margin
                row = rng.choice((0, 0, 0, 1, 1, 2))
                rootp = loc + up * (sgn * 0.00006 * row) - forward * (0.00012 * row)
                # position along the lid from the nasal (0) to the temporal (1) corner
                g = (x - ap.x_min) / (ap.x_max - ap.x_min)
                if outward < 0:
                    g = 1.0 - g
                if lid == "upper":
                    profile = 0.45 + 0.55 * math.sin(math.pi * min(1.0, 0.18 + 0.9 * g))
                    length = LASH_LEN_UPPER * profile * rng.uniform(0.72, 1.12)
                    # leave the lid forward and slightly down, then curl up gently
                    a0, a1 = math.radians(rng.uniform(-12, 2)), math.radians(rng.uniform(36, 60))
                else:
                    profile = 0.4 + 0.6 * math.sin(math.pi * min(1.0, 0.15 + 0.85 * g))
                    length = LASH_LEN_LOWER * profile * rng.uniform(0.6, 1.1)
                    a0, a1 = math.radians(rng.uniform(-10, 8)), math.radians(rng.uniform(22, 44))
                # fan toward the temple at the outer end, toward the nose at the inner end, plus
                # each lash's own sideways drift and twist so neighbours cross instead of forming a comb
                fan0 = math.radians((g - 0.35) * 34.0 + rng.uniform(-11, 11)) * outward
                twist = math.radians(rng.uniform(-12, 12))
                d0 = (forward * math.cos(a0) + up * (sgn * math.sin(a0))).normalized()
                start = rootp - d0 * LASH_ROOT_DEPTH               # begins inside the skin
                pts = [start, rootp.copy()]
                p = rootp.copy()
                steps = 8
                for i in range(1, steps + 1):
                    t = i / steps
                    a = a0 + (a1 - a0) * t ** 1.2
                    fan = fan0 + twist * t
                    d = (forward * math.cos(a) + up * (sgn * math.sin(a))) * math.cos(fan) + right * math.sin(fan)
                    p = p + d.normalized() * (length / steps)
                    pts.append(p.copy())
                strands.append((lid, side, k, pts))
                made += 1
        # clumping: pull each lash's outer half toward the mean of its clump (2-4 neighbours)
        for lid in ("upper", "lower"):
            group = [st for st in strands if st[0] == lid and st[1] == side]
            group.sort(key=lambda st: st[2])
            i = 0
            while i < len(group):
                size = rng.choice((1, 2, 2, 3))
                clump = group[i:i + size]
                i += size
                tip = sum((st[3][-1] for st in clump), Vector()) / len(clump)
                for st in clump:
                    pts = st[3]
                    n_p = len(pts)
                    for j in range(n_p):
                        w = LASH_CLUMP * (j / (n_p - 1)) ** 2
                        pts[j] = pts[j] * (1 - w) + (tip + (pts[j] - pts[-1])) * w if j < n_p - 1 else pts[j] * (1 - LASH_CLUMP) + tip * LASH_CLUMP
                    rib.add(pts, 0.000080 if lid == "upper" else 0.000055, 0.000008)
    ob = rib.to_object("Human.eyelashes_strands", hair_material("Eyelash_Strand", (0.010, 0.0075, 0.006), 0.45, 0.0, sss=0.0))
    # Lash strands neither cast shadows nor show in the cornea's mirror reflection. Physically
    # they would stripe the glint with ~10 %-wide shadows, but at practical sample counts those
    # stripes render as broken noise whose look depends on the sample count. Switching off BOTH
    # ray types (one alone leaves half-strength stripes) gives a clean glint that the label model
    # (skin / nose / lids as occluders) describes exactly.
    ob.visible_shadow = False
    ob.visible_glossy = False
    log("lash strands: %d" % made)
    return ob


def build_brow_strands(forward, up, cam_pos):
    """Eyebrow hairs scattered over the MakeHuman brow card, denser where its texture is
    denser, following the natural growth pattern (up at the inner end, outward along the brow,
    slightly down at the tail). The card stays underneath at reduced opacity as fine down."""
    import random
    import numpy as np
    card = next((o for o in bpy.data.objects if o.type == "MESH" and "eyebrow" in o.name.lower()), None)
    if card is None:
        log("WARNING: no eyebrow card found; skipping brow strands")
        return None
    rng = random.Random(4321)
    right = up.cross(forward).normalized()
    mat = card.active_material
    tex = next(n for n in mat.node_tree.nodes if n.type == "TEX_IMAGE")
    img = tex.image
    w, h = img.size
    px = np.empty(w * h * 4, np.float32)
    img.pixels.foreach_get(px)
    alpha = px.reshape(h, w, 4)[..., 3]
    dg = bpy.context.evaluated_depsgraph_get()
    ev = card.evaluated_get(dg)
    me = ev.to_mesh()
    mw = ev.matrix_world.copy()
    me.calc_loop_triangles()
    uv = me.uv_layers.active.data
    tris = []
    for tri in me.loop_triangles:
        ps = [mw @ me.vertices[i].co for i in tri.vertices]
        uvs = [Vector(uv[l].uv) for l in tri.loops]
        area = (ps[1] - ps[0]).cross(ps[2] - ps[0]).length * 0.5
        tris.append((ps, uvs, area))
    ev.to_mesh_clear()
    total = sum(t[2] for t in tris)
    cum = []
    acc = 0.0
    for t in tris:
        acc += t[2]
        cum.append(acc / total)
    import bisect
    centre_x = sum(sum((p.dot(right) for p in t[0]), 0.0) for t in tris) / (3 * len(tris))
    rib = Ribbons(cam_pos)
    skin = _bvh_of(bpy.data.objects["Human"])
    hairs = []
    cands = []
    made = 0
    tries = 0
    while made < BROW_HAIRS and tries < BROW_HAIRS * 12:
        tries += 1
        t = tris[min(bisect.bisect_left(cum, rng.random()), len(tris) - 1)]
        r1, r2 = rng.random(), rng.random()
        if r1 + r2 > 1:
            r1, r2 = 1 - r1, 1 - r2
        p = t[0][0] + (t[0][1] - t[0][0]) * r1 + (t[0][2] - t[0][0]) * r2
        # the MakeHuman card floats 0.8-3 mm off the skin: root the hair on the skin itself
        near = skin.find_nearest(p)
        if near[0] is not None:
            p = near[0]
        q = t[1][0] + (t[1][1] - t[1][0]) * r1 + (t[1][2] - t[1][0]) * r2
        a = alpha[min(h - 1, max(0, int(q.y * h))), min(w - 1, max(0, int(q.x * w)))]
        if rng.random() > a ** 0.8:
            continue
        nrm = (t[0][1] - t[0][0]).cross(t[0][2] - t[0][0]).normalized()
        if nrm.dot(forward) < 0:
            nrm = -nrm
        x = p.dot(right) - centre_x
        if near[0] is not None:
            nrm = near[1].normalized()
            if nrm.dot(forward) < 0:
                nrm = -nrm
        cands.append((p, nrm, abs(x), 1.0 if x > 0 else -1.0))
        made += 1

    # position of each follicle across its brow: 0 = lower edge, 1 = upper edge
    import numpy as np
    across = {}
    for side_out in (1.0, -1.0):
        idx = [i for i, cd in enumerate(cands) if cd[3] == side_out]
        if not idx:
            continue
        axs = np.array([cands[i][2] for i in idx])
        zs = np.array([cands[i][0].dot(up) for i in idx])
        nb = 24
        a0, a1 = axs.min(), axs.max()
        bins = np.minimum(((axs - a0) / max(a1 - a0, 1e-6) * nb).astype(int), nb - 1)
        lo_b, hi_b = np.zeros(nb), np.zeros(nb)
        for k in range(nb):
            sel = zs[np.abs(bins - k) <= 1]
            lo_b[k], hi_b[k] = np.percentile(sel, 5), np.percentile(sel, 95)
        ker = np.ones(5) / 5
        lo_b = np.convolve(np.pad(lo_b, 2, mode="edge"), ker, mode="valid")
        hi_b = np.convolve(np.pad(hi_b, 2, mode="edge"), ker, mode="valid")
        for i, z, k in zip(idx, zs, bins):
            across[i] = float(np.clip((z - lo_b[k]) / max(hi_b[k] - lo_b[k], 1e-4), 0.0, 1.0))

    made = 0
    for ci, (p, nrm, ax, out) in enumerate(cands):
        wv = across.get(ci, 0.5)
        # growth direction: angle from "up" toward the temple, by distance from the midline
        knots = [(0.010, 10.0), (0.020, 35.0), (0.030, 72.0), (0.045, 88.0), (0.060, 108.0)]
        ang = knots[-1][1]
        for (x0, a0), (x1, a1) in zip(knots, knots[1:]):
            if ax <= x0:
                ang = knots[0][1]
                break
            if ax <= x1:
                ang = a0 + (a1 - a0) * (ax - x0) / (x1 - x0)
                break
        # interleave instead of layering: upper hairs angle down over the brow, lower hairs up
        # (strongest along the body; the upward-growing head is left alone)
        body = min(1.0, max(0.0, (ax - 0.014) / 0.012))
        ang += body * BROW_INTERLEAVE * (2.0 * wv - 1.0)
        ang = math.radians(ang + rng.uniform(-12, 12))
        d = up * math.cos(ang) + right * (out * math.sin(ang))
        d = (d - nrm * d.dot(nrm)).normalized()                    # along the skin
        length = (0.0045 + 0.0045 * min(1.0, ax / 0.035)) * rng.uniform(0.7, 1.15)
        lift = math.radians(rng.uniform(4, 10))
        pts = [p - nrm * 0.00005]                                   # starts inside the skin
        cur = pts[0].copy()
        for i in range(1, 6):
            tt = i / 5
            e = math.radians(13) * tt ** 1.5                        # tips bend back toward the skin
            dirv = d * math.cos(lift - e) + nrm * math.sin(lift - e)
            cur = cur + dirv.normalized() * (length / 5)
            pts.append(cur.copy())
        hairs.append((pts, out, ax))
        made += 1
    # Clean-up (the brow's look is otherwise unchanged):
    #  1. hairs rooted on the lower edge must not run below the brow: cut them where they cross
    #     a smooth lower boundary (otherwise they gather into a separate line under the brow);
    #  2. every hair stays within BROW_MAX_LIFT of the skin, so none floats off where the brow
    #     ridge curves away.
    import numpy as np
    nb = 30
    for side_out in (1.0, -1.0):
        hs = [hh for hh in hairs if hh[1] == side_out]
        if not hs:
            continue
        axs = np.array([hh[2] for hh in hs])
        zs = np.array([hh[0][0].dot(up) for hh in hs])
        a0, a1 = axs.min(), axs.max()
        bins = np.minimum(((axs - a0) / max(a1 - a0, 1e-6) * nb).astype(int), nb - 1)
        low = np.zeros(nb)
        for k in range(nb):
            sel = zs[np.abs(bins - k) <= 1]
            low[k] = np.percentile(sel, 4) if len(sel) else zs.min()
        low = np.convolve(np.pad(low, 2, mode="edge"), np.ones(5) / 5, mode="valid")
        for pts, _o, _ax in hs:
            margin = BROW_LOW_MARGIN * (0.4 + 2.2 * rng.random() ** 2)   # ragged, not a ruled line
            keep = [pts[0]]
            for q in pts[1:]:
                qa = abs(q.dot(right) - centre_x)
                k = int(min(nb - 1, max(0, (qa - a0) / max(a1 - a0, 1e-6) * nb)))
                if q.dot(up) < low[k] - margin:
                    break
                near = skin.find_nearest(q)
                if near[0] is not None:
                    gap = (q - near[0]).length
                    if gap > BROW_MAX_LIFT:
                        q = near[0] + (q - near[0]) * (BROW_MAX_LIFT / gap)
                keep.append(q)
            if len(keep) >= 3:
                rib.add(keep, 0.000040, 0.000006)
    ob = rib.to_object("BrowStrands", hair_material("Eyebrow_Strand", (0.062, 0.040, 0.027), 0.62, 0.0, sss=0.15))
    # the card sits on the skin (it floated up to 3 mm off it) ...
    sw = card.modifiers.new("OnSkin", "SHRINKWRAP")
    sw.target = bpy.data.objects["Human"]
    sw.wrap_method = "NEAREST_SURFACEPOINT"
    sw.offset = 0.00004
    # ... and becomes a faint under-layer of fine down hair
    for slot in card.material_slots:
        m = slot.material
        bsdf = next((n for n in m.node_tree.nodes if n.type == "BSDF_PRINCIPLED"), None)
        if bsdf is None:
            continue
        nt = m.node_tree
        mul = nt.nodes.new("ShaderNodeMath")
        mul.operation = "MULTIPLY"
        mul.inputs[1].default_value = BROW_CARD_OPACITY
        if bsdf.inputs["Alpha"].links:
            nt.links.new(bsdf.inputs["Alpha"].links[0].from_socket, mul.inputs[0])
        else:
            mul.inputs[0].default_value = bsdf.inputs["Alpha"].default_value
        nt.links.new(mul.outputs[0], bsdf.inputs["Alpha"])
    log("brow strands: %d (from %d samples)" % (made, tries))
    return ob



def conjunctiva_ring(name, r_in=None, r_out=0.020, depth=0.0006, segs=128, rings=10):
    """Flat annulus facing the camera, `depth` metres in front of the globe centre. Inside
    r_in it would lie behind the globe's surface (and be hidden by it), so it starts just inside
    the globe's silhouette. Vertex attribute "fade" darkens it toward the outside."""
    rs = EYE_RADIUS + SHELL_GAP
    if r_in is None:
        r_in = math.sqrt(rs * rs - depth * depth) - 0.0003
    mesh = bpy.data.meshes.new(name)
    bm = bmesh.new()
    layer = bm.verts.layers.float.new("fade")
    grid = []
    for i in range(rings + 1):
        r = r_in + (r_out - r_in) * (i / rings) ** 1.6
        row = []
        for k in range(segs):
            a = 2 * math.pi * k / segs
            v = bm.verts.new((r * math.cos(a), r * math.sin(a), depth))
            v[layer] = 1.0 - i / rings
            row.append(v)
        grid.append(row)
    for i in range(rings):
        for k in range(segs):
            k2 = (k + 1) % segs
            f = bm.faces.new((grid[i][k], grid[i][k2], grid[i + 1][k2], grid[i + 1][k]))
            f.smooth = True
    bm.normal_update()
    if sum(f.normal.z for f in bm.faces) < 0:
        bmesh.ops.reverse_faces(bm, faces=bm.faces)
    bm.to_mesh(mesh)
    bm.free()
    return bpy.data.objects.new(name, mesh)


def build_wet_details(centres, apertures, forward, up, mats, human=None):
    """Caruncle and plica (the pink tissue in the inner corner) and the tear meniscus on the
    lower lid. They belong to the head, not the eyeball, so they stay put while the globe
    rotates beneath them."""
    right = up.cross(forward).normalized()
    mid = (centres["L"] + centres["R"]) * 0.5
    rs = EYE_RADIUS + SHELL_GAP

    # Caruncle: salmon-pink, wet, lobulated tissue (sRGB ~ 218,149,146 in the middle), with a
    # sharp tear-film coat whose highlight the lumps break into specks. Plica semilunaris: a
    # paler pink fold between it and the sclera. (The earlier values, linear 0.76/0.50/0.46,
    # showed as near-white sRGB 226,188,180 and the caruncle read as sclera.)
    car_mat = caruncle_material("Eye_Caruncle", (0.70, 0.30, 0.28), (0.74, 0.44, 0.42), 1.0, soft=0.7,
                                coat=1.0, roughness=0.3, coat_roughness=0.04,
                                bump_strength=0.8, bump_distance=0.0002, lobule_scale=1600.0)
    plica_mat = caruncle_material("Eye_Plica", (0.64, 0.34, 0.32), (0.72, 0.48, 0.45), 0.6, soft=1.0,
                                  coat=1.0, roughness=0.35, coat_roughness=0.04, bump_strength=0.3)
    # lid rims, conjunctiva and corner fill below: unchanged
    conj_mat = caruncle_material("Eye_Conjunctiva", (0.58, 0.34, 0.30), (0.42, 0.25, 0.22), 1.0,
                                 soft=0.001, coat=0.05, roughness=0.6)
    rim_mat = caruncle_material("Eye_LidRim", (0.60, 0.36, 0.32), (0.66, 0.44, 0.38), 1.0,
                                soft=0.6, coat=0.06, roughness=0.6)
    fill_mat = caruncle_material("Eye_CornerFill", (0.44, 0.27, 0.24), (0.50, 0.34, 0.30), 0.9,
                                 soft=1.0, coat=0.04, roughness=0.65)

    tear_objs = []
    for side in ("L", "R"):
        c = centres[side]
        ap = apertures[side]
        axis = (mid + forward * FIXATION_DISTANCE_M - c).normalized()
        nose = -1.0 if (c - mid).dot(right) > 0 else 1.0     # direction toward the nose along `right`
        corner = ap.corner_min if nose < 0 else ap.corner_max

        # ---- caruncle: the soft tissue filling the inner corner of the lid opening ----
        # lid surface depth just beyond the corner tip (ray cast from the front), so the mound
        # rises to just below lid level there
        tip_depth = None
        if human is not None:
            skin = _bvh_of(human)
            depths = []
            for dx, dz in ((0.0006, 0.0), (0.0003, 0.0009), (0.0003, -0.0009)):
                probe = c + right * (corner[0] + nose * dx) + up * (corner[1] + dz)
                hit = skin.ray_cast(probe + forward * 0.05, -forward, 0.1)
                if hit[0] is not None:
                    depths.append((hit[0] - c).dot(forward))
            if depths:
                tip_depth = min(depths) - 0.0007
        mesh = shell_patch("Caruncle." + side,
                           corner_patch_fn(ap, corner[0], nose, -0.0004, CARUNCLE_WIDTH, 0.0004, CARUNCLE_HEIGHT, 0.18,
                                           tip_depth=tip_depth))
        ob = bpy.data.objects.new("Caruncle." + side, mesh)
        ob.matrix_world = Matrix.Translation(c) @ Matrix((right, up, forward)).transposed().to_4x4()
        mesh.materials.append(car_mat)
        bpy.context.scene.collection.objects.link(ob)

        # ---- plica semilunaris: a faint crescent fold just outside the caruncle ----
        mesh = shell_patch("Plica." + side,
                           corner_patch_fn(ap, corner[0], nose, CARUNCLE_WIDTH - 0.0008, CARUNCLE_WIDTH + 0.0012,
                                           0.0003, 0.00003, 0.0, both_ends=True), nu=14)
        ob = bpy.data.objects.new("Plica." + side, mesh)
        ob.matrix_world = Matrix.Translation(c) @ Matrix((right, up, forward)).transposed().to_4x4()
        mesh.materials.append(plica_mat)
        bpy.context.scene.collection.objects.link(ob)

        # ---- outer corner: pale conjunctiva facing the viewer instead of the globe's dark limb ----
        outer = ap.corner_max if nose < 0 else ap.corner_min
        if not OUTER_CORNER_FILL:
            outer = None
        # ---- conjunctival lining: what a line of sight past the eyeball's edge really meets is
        #      the pink lining of the conjunctival sac, not a dark socket. A head-fixed ring just
        #      behind the globe's outline; the globe hides its inner part, the lids most of the rest.
        if CONJUNCTIVA_RING:
            ring = conjunctiva_ring("Conjunctiva." + side)
            ring.matrix_world = Matrix.Translation(c) @ Matrix((right, up, forward)).transposed().to_4x4()
            ring.data.materials.append(conj_mat)
            bpy.context.scene.collection.objects.link(ring)
            ring.visible_shadow = False

        if outer is not None:
            mesh = shell_patch("CornerFill." + side,
                               corner_patch_fn(ap, outer[0], -nose, -0.0003, 0.0020, 0.0001, 0.00002, 0.0, both_ends=True))
            ob = bpy.data.objects.new("CornerFill." + side, mesh)
            ob.matrix_world = Matrix.Translation(c) @ Matrix((right, up, forward)).transposed().to_4x4()
            mesh.materials.append(fill_mat)
            bpy.context.scene.collection.objects.link(ob)

        # ---- lid rims: the pale pink margin of each lid, lining the gap between lid and eye.
        #      They move with the lids (same shape keys), so they are returned with the tear line.
        for lid, inside in (("Upper", 0.0), ("Lower", LID_RIM_INSIDE)):
            sgn = 1.0 if lid == "Upper" else -1.0

            def rim_fn(u, t, sgn=sgn, inside=inside):
                # strictly inside the opening: stop short of the caruncle at the inner end
                xa = ap.x_min + (0.6 * CARUNCLE_WIDTH if nose < 0 else 0.0003)
                xb = ap.x_max - (0.6 * CARUNCLE_WIDTH if nose > 0 else 0.0003)
                x = xa + (xb - xa) * u
                zl, zu = ap.margins(x)
                edge = zu if sgn > 0 else zl
                w = 0.5 * (t + 1.0)                                  # 0 = inner edge, 1 = under the lid
                off = -inside + w * (inside + LID_RIM_UNDER)         # metres outside the margin
                z = edge + sgn * off
                fade = smoothstep(-inside, -0.15 * inside, off) if inside > 0 else 1.0
                fade *= smoothstep(0.0, 0.08, u) * smoothstep(0.0, 0.08, 1.0 - u)   # soft ends
                # ride on top of the corneal bulge where a margin crosses the cornea, so the
                # rim never ends up inside the refracting shell
                rs_ = EYE_RADIUS + SHELL_GAP
                rho = math.hypot(x, z)
                bulge = shell_radius(math.asin(min(1.0, rho / rs_))) - rs_ if rho < rs_ else 0.0
                return x, z, bulge + (0.00006 if sgn > 0 else 0.00010), fade, None
            mesh = shell_patch("LidRim%s.%s" % (lid, side), rim_fn, nu=72, nt=8)
            ob = bpy.data.objects.new("LidRim%s.%s" % (lid, side), mesh)
            ob.matrix_world = Matrix.Translation(c) @ Matrix((right, up, forward)).transposed().to_4x4()
            mesh.materials.append(rim_mat)
            bpy.context.scene.collection.objects.link(ob)
            ob.visible_shadow = False
            ob.visible_glossy = False      # a thin liner under the lid edge: keep it out of the
            tear_objs.append(ob)           # cornea's mirror image so glints match the label model

        # ---- tear meniscus along the lower lid margin ----
        pts = []
        n = 48
        x0, x1 = ap.x_min + 0.0022, ap.x_max - 0.0022
        for i in range(n + 1):
            x = x0 + (x1 - x0) * i / n
            zl, _zu = ap.margins(x)
            z = zl + 0.00012
            d = right * x + up * z + forward * math.sqrt(max(rs ** 2 - x * x - z * z, 1e-8))
            d.normalize()
            pts.append(c + d * (shell_radius(d.angle(axis)) + 0.00010))
        mesh = tube_mesh("TearLine." + side, pts, 0.00024, forward)
        ob = bpy.data.objects.new("TearLine." + side, mesh)
        mesh.materials.append(mats["cornea"])
        bpy.context.scene.collection.objects.link(ob)
        ob.visible_shadow = False
        tear_objs.append(ob)
    return tear_objs


# --------------------------------------------------------------------------- #
# Human
# --------------------------------------------------------------------------- #
def build_human():
    base = mpfb_module()
    HumanService = importlib.import_module(base + ".services.humanservice").HumanService
    TargetService = importlib.import_module(base + ".services.targetservice").TargetService

    bm = HumanService.create_human(scale=HUMAN_SCALE, macro_detail_dict=MACROS)
    tdir = os.path.join(os.path.dirname(importlib.import_module(base).__file__), "data", "targets")
    for name, weight in EYE_TARGETS.items():
        for side in "lr":
            TargetService.load_target(bm, os.path.join(tdir, "eyes", "%s-eye-%s.target.gz" % (side, name)),
                                      weight=weight, name="%s-eye-%s" % (side, name))
    TargetService.bake_targets(bm)
    bpy.context.view_layer.update()
    bm.name = "Human"
    log("basemesh dims (m):", tuple(round(d, 4) for d in bm.dimensions))

    # --- measurements from the model's own helper geometry (before rig/modifiers) ---
    meas = {}
    for side, tag in (("L", "l"), ("R", "r")):
        joint = bbox_centre(group_points(bm, "joint-%s-eye" % tag))
        look = bbox_centre(group_points(bm, "joint-%s-eye-target" % tag))
        helper = group_points(bm, "helper-%s-eye" % tag)
        meas[side] = {"joint": joint, "look": look, "helper": helper}
    head_lo = bbox_centre(group_points(bm, "joint-head"))
    head_hi = bbox_centre(group_points(bm, "joint-head-2"))

    # Face axes, detected from the model:
    #   lateral axis  = line through the two eye centres (avatar right -> left)
    #   up            = world axis closest to the head's long axis (the model stands upright)
    #   forward       = up x lateral, sign chosen so it points the way the eyes look
    x_axis = (meas["L"]["joint"] - meas["R"]["joint"]).normalized()
    up, _ = snap_axis(head_hi - head_lo, 45.0)
    up = (up - x_axis * up.dot(x_axis)).normalized()
    forward = up.cross(x_axis).normalized()
    look_dir = (meas["L"]["look"] - meas["L"]["joint"]) + (meas["R"]["look"] - meas["R"]["joint"])
    if forward.dot(look_dir) < 0:
        forward = -forward
    log("axes: lateral", tuple(round(c, 4) for c in x_axis), "up", tuple(round(c, 4) for c in up),
        "forward", tuple(round(c, 4) for c in forward))

    extend_inner_corners(bm, meas, forward, up, INNER_CORNER_EXTENSION, OUTER_CORNER_PULL)
    centres, apertures = seat_eyes(bm, meas, forward, up)
    fit_lids_to_globes(bm, meas, centres, apertures, forward, up)

    rig = HumanService.add_builtin_rig(bm, "default", import_weights=True)
    if rig is None:
        rig = next(o for o in bpy.data.objects if o.type == "ARMATURE")
    rig.name = "Human.rig"

    for kind, name in (("Eyebrows", "eyebrow001"), ("Eyelashes", "eyelashes01")):
        path = os.path.join(ASSETS, kind.lower(), name, name + ".mhclo")
        try:
            HumanService.add_mhclo_asset(path, bm, asset_type=kind, subdiv_levels=0, material_type="MAKESKIN")
            log("added", kind, name)
        except Exception as e:  # cosmetic only; never fail the build for it
            log("WARNING: could not add", kind, name, "->", repr(e))
    # Clothing, so the avatar is dressed when the .blend is opened. It is disabled in renders
    # (hide_render): Cycles leaves it out entirely, so the official frames, their lighting and
    # the eye reflections are exactly what they are without it. (Blender's "Rendered" viewport
    # mode ignores hide_render; that preview is not part of the deliverables.)
    for name in CLOTHES:
        path = os.path.join(ASSETS, "clothes", name, name + ".mhclo")
        try:
            ob = HumanService.add_mhclo_asset(path, bm, asset_type="Clothes", subdiv_levels=0,
                                              material_type="MAKESKIN")
            ob.hide_render = True
            log("added clothes", name, "(disabled in renders)")
        except Exception as e:  # cosmetic only; never fail the build for it
            log("WARNING: could not add clothes", name, "->", repr(e))
    # MPFB also masks the body under each garment ("Delete.<name>" MASK modifiers). In renders the
    # body must stay complete, or the light it bounces onto the face changes (measured: up to
    # 62/255), so the masks never render. They also stay off during the rest of the build: the
    # brow strands are sampled on the evaluated skin, and a masked mesh renumbers its faces (the
    # hairs then grew in different places). enable_clothes_masks() turns them on for the
    # viewport only, just before saving, so no skin pokes through the clothes there.
    for m in bm.modifiers:
        if m.type == "MASK" and m.vertex_group.startswith("Delete."):
            m.show_render = False
            m.show_viewport = False
    groom_lashes(centres, apertures, forward, up)

    return bm, rig, meas, forward, up, centres, apertures


def enable_clothes_masks():
    """Viewport only: hide the body under the clothes (see build_human)."""
    human = bpy.data.objects.get("Human")
    if human is None:
        return
    for m in human.modifiers:
        if m.type == "MASK" and m.vertex_group.startswith("Delete."):
            m.show_viewport = True
            m.show_render = False


