# Eyeball geometry
# --------------------------------------------------------------------------- #
def revolve(name, profile, segments, uv_fn, mat_fn):
    """Surface of revolution about local +Z. profile = [(rho, z, tag), ...] front to back.

    uv_fn(rho, z, phi, tag) -> (u, v); mat_fn(tag_a, tag_b) -> material index for a band.
    """
    mesh = bpy.data.meshes.new(name)
    bm = bmesh.new()
    uv_layer = bm.loops.layers.uv.new("UVMap")
    rings = []
    for rho, z, tag in profile:
        if rho < 1e-9:
            rings.append([bm.verts.new((0.0, 0.0, z))])
        else:
            rings.append([bm.verts.new((rho * math.cos(2 * math.pi * s / segments),
                                        rho * math.sin(2 * math.pi * s / segments), z))
                          for s in range(segments)])

    def set_uv(face, quads):
        for loop, (ri, s) in zip(face.loops, quads):
            rho, z, tag = profile[ri]
            loop[uv_layer].uv = uv_fn(rho, z, 2 * math.pi * s / segments, face_tag[0])

    face_tag = [None]
    for i in range(len(profile) - 1):
        a, b = rings[i], rings[i + 1]
        face_tag[0] = profile[i + 1][2] if len(a) == 1 else profile[i][2] if len(b) == 1 else profile[i + 1][2]
        mat = mat_fn(profile[i][2], profile[i + 1][2])
        for s in range(segments):
            s2 = (s + 1) % segments
            if len(a) == 1 and len(b) == 1:
                continue
            if len(a) == 1:
                f = bm.faces.new((a[0], b[s], b[s2]))
                set_uv(f, [(i, s + 0.5), (i + 1, s), (i + 1, s + 1)])
            elif len(b) == 1:
                f = bm.faces.new((a[s], b[0], a[s2]))
                set_uv(f, [(i, s), (i + 1, s + 0.5), (i, s + 1)])
            else:
                f = bm.faces.new((a[s], b[s], b[s2], a[s2]))
                set_uv(f, [(i, s), (i + 1, s), (i + 1, s + 1), (i, s + 1)])
            f.material_index = mat
            f.smooth = True
    bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    bm.to_mesh(mesh)
    bm.free()
    return mesh


def eye_profiles():
    r = EYE_RADIUS
    limbus = math.asin(IRIS_RADIUS / r)
    z_l = r * math.cos(limbus)
    z_p = z_l - IRIS_DEPTH

    inner = [(0.0, z_p, "pupil"), (PUPIL_RADIUS * 0.5, z_p, "pupil"), (PUPIL_RADIUS, z_p, "pupil")]
    n_iris = 16
    for i in range(1, n_iris + 1):
        t = i / n_iris
        rho = PUPIL_RADIUS + (IRIS_RADIUS - PUPIL_RADIUS) * t
        z = z_p + (z_l - z_p) * (t ** 2.2)        # shallow bowl, flat near the pupil
        inner.append((rho, z, "iris"))
    n_scl = 56
    for i in range(1, n_scl + 1):
        a = limbus + (math.pi - limbus) * i / n_scl
        inner.append((r * math.sin(a) if i < n_scl else 0.0, r * math.cos(a), "sclera"))

    rs = r + SHELL_GAP
    limbus_s = math.asin(IRIS_RADIUS / rs)
    z_ls = rs * math.cos(limbus_s)
    z_c = z_ls - math.sqrt(CORNEA_CURVATURE ** 2 - IRIS_RADIUS ** 2)
    shell = []
    n_cor = 40
    for i in range(0, n_cor + 1):
        rho = IRIS_RADIUS * i / n_cor
        shell.append((rho, z_c + math.sqrt(CORNEA_CURVATURE ** 2 - rho ** 2), "cornea"))
    n_sh = 56
    for i in range(1, n_sh + 1):
        a = limbus_s + (math.pi - limbus_s) * i / n_sh
        shell.append((rs * math.sin(a) if i < n_sh else 0.0, rs * math.cos(a), "shell"))
    apex = z_c + CORNEA_CURVATURE
    return inner, shell, z_p, apex


def eye_uv(rho, z, phi, tag):
    if tag in ("pupil", "iris"):
        d = 0.5 * min(rho / IRIS_RADIUS, 1.0)
    else:
        d = 0.5 * math.atan2(rho, z) / math.pi
    return (0.5 + d * math.cos(phi), 0.5 + d * math.sin(phi))


def image(name, colorspace="sRGB"):
    path = os.path.join(TEX, name)
    img = bpy.data.images.load(path, check_existing=True)
    img.colorspace_settings.name = colorspace
    return img


def nodes_reset(mat):
    mat.use_nodes = True
    nt = mat.node_tree
    nt.nodes.clear()
    out = nt.nodes.new("ShaderNodeOutputMaterial")
    out.location = (600, 0)
    return nt, out


def make_eye_materials():
    mats = {}

    m = bpy.data.materials.new("Eye_Sclera")
    nt, out = nodes_reset(m)
    tex = nt.nodes.new("ShaderNodeTexImage"); tex.image = image("sclera_color.png"); tex.location = (-400, 0)
    tex.extension = "EXTEND"
    b = nt.nodes.new("ShaderNodeBsdfPrincipled"); b.location = (200, 0)
    nt.links.new(tex.outputs["Color"], b.inputs["Base Color"])
    b.inputs["Roughness"].default_value = 0.55
    b.inputs["Subsurface Weight"].default_value = 0.6
    b.inputs["Subsurface Radius"].default_value = (1.0, 0.45, 0.35)
    b.inputs["Subsurface Scale"].default_value = 0.0015
    b.inputs["Specular IOR Level"].default_value = 0.2
    nt.links.new(b.outputs["BSDF"], out.inputs["Surface"])
    mats["sclera"] = m

    m = bpy.data.materials.new("Eye_Iris")
    nt, out = nodes_reset(m)
    tex = nt.nodes.new("ShaderNodeTexImage"); tex.image = image("iris_color.png"); tex.location = (-400, 0)
    tex.extension = "EXTEND"
    b = nt.nodes.new("ShaderNodeBsdfPrincipled"); b.location = (200, 0)
    # iris colour control for dataset variation: 0 = blue-grey, 1 = dark brown
    tex2 = nt.nodes.new("ShaderNodeTexImage"); tex2.image = image("iris_color_brown.png")
    tex2.extension = "EXTEND"
    nt.links.new(tex.inputs["Vector"].links[0].from_socket, tex2.inputs["Vector"]) if tex.inputs["Vector"].links else None
    melanin = nt.nodes.new("ShaderNodeValue"); melanin.name = "IrisMelanin"; melanin.label = "IrisMelanin"
    melanin.outputs[0].default_value = 0.0
    mixc = nt.nodes.new("ShaderNodeMix"); mixc.data_type = "RGBA"
    nt.links.new(melanin.outputs[0], mixc.inputs[0])
    nt.links.new(tex.outputs["Color"], mixc.inputs[6])
    nt.links.new(tex2.outputs["Color"], mixc.inputs[7])
    nt.links.new(mixc.outputs[2], b.inputs["Base Color"])
    b.inputs["Roughness"].default_value = 0.7
    b.inputs["Specular IOR Level"].default_value = 0.15
    bump = nt.nodes.new("ShaderNodeBump"); bump.location = (-100, -250)
    bump.inputs["Strength"].default_value = 0.35
    bump.inputs["Distance"].default_value = 0.0002
    nt.links.new(tex.outputs["Color"], bump.inputs["Height"])
    nt.links.new(bump.outputs["Normal"], b.inputs["Normal"])
    nt.links.new(b.outputs["BSDF"], out.inputs["Surface"])
    mats["iris"] = m

    m = bpy.data.materials.new("Eye_Pupil")
    nt, out = nodes_reset(m)
    b = nt.nodes.new("ShaderNodeBsdfDiffuse")
    b.inputs["Color"].default_value = (0.0, 0.0, 0.0, 1.0)
    nt.links.new(b.outputs["BSDF"], out.inputs["Surface"])
    mats["pupil"] = m

    # Cornea + tear film: clear refractive shell. Shadow rays pass straight through so the
    # iris and sclera underneath are lit without needing caustics.
    m = bpy.data.materials.new("Eye_Cornea")
    nt, out = nodes_reset(m)
    glass = nt.nodes.new("ShaderNodeBsdfPrincipled"); glass.location = (-100, 100)
    glass.inputs["Base Color"].default_value = (1, 1, 1, 1)
    glass.inputs["Roughness"].default_value = 0.02
    glass.inputs["IOR"].default_value = CORNEA_IOR
    glass.inputs["Transmission Weight"].default_value = 1.0
    transp = nt.nodes.new("ShaderNodeBsdfTransparent"); transp.location = (-100, -200)
    lp = nt.nodes.new("ShaderNodeLightPath"); lp.location = (-400, 300)
    mix = nt.nodes.new("ShaderNodeMixShader"); mix.location = (300, 0)
    nt.links.new(lp.outputs["Is Shadow Ray"], mix.inputs["Fac"])
    nt.links.new(glass.outputs["BSDF"], mix.inputs[1])
    nt.links.new(transp.outputs["BSDF"], mix.inputs[2])
    nt.links.new(mix.outputs["Shader"], out.inputs["Surface"])
    mats["cornea"] = m

    # Tear film over the white of the eye: wet but not a mirror. Mostly transparent (the shell
    # sits 0.06 mm above the sclera, so no refraction is needed), with a soft, blurred sheen whose
    # strength follows Fresnel; it no longer mirrors the corner tissue and lids like glass.
    m = bpy.data.materials.new("Eye_ScleraFilm")
    nt, out = nodes_reset(m)
    transp = nt.nodes.new("ShaderNodeBsdfTransparent")
    gloss = nt.nodes.new("ShaderNodeBsdfGlossy")
    gloss.inputs["Roughness"].default_value = SCLERA_FILM_ROUGHNESS
    lw = nt.nodes.new("ShaderNodeLayerWeight")
    lw.inputs["Blend"].default_value = 0.15
    scale = nt.nodes.new("ShaderNodeMath"); scale.operation = "MULTIPLY"
    scale.inputs[1].default_value = SCLERA_FILM_SHEEN
    nt.links.new(lw.outputs["Fresnel"], scale.inputs[0])
    mix = nt.nodes.new("ShaderNodeMixShader")
    nt.links.new(scale.outputs[0], mix.inputs["Fac"])
    nt.links.new(transp.outputs["BSDF"], mix.inputs[1])
    nt.links.new(gloss.outputs["BSDF"], mix.inputs[2])
    lp = nt.nodes.new("ShaderNodeLightPath")
    shadow = nt.nodes.new("ShaderNodeMixShader")
    transp2 = nt.nodes.new("ShaderNodeBsdfTransparent")
    nt.links.new(lp.outputs["Is Shadow Ray"], shadow.inputs["Fac"])
    nt.links.new(mix.outputs["Shader"], shadow.inputs[1])
    nt.links.new(transp2.outputs["BSDF"], shadow.inputs[2])
    nt.links.new(shadow.outputs["Shader"], out.inputs["Surface"])
    mats["sclera_film"] = m
    return mats


def bone_parent(obj, rig, bone_name, world_matrix):
    obj.parent = rig
    obj.parent_type = "BONE"
    obj.parent_bone = bone_name
    bpy.context.view_layer.update()
    bone = rig.data.bones[bone_name]
    # Bone parenting attaches at the bone TAIL: parent matrix = rig * bone * T(0, length, 0)
    parent_world = rig.matrix_world @ bone.matrix_local @ Matrix.Translation((0.0, bone.length, 0.0))
    obj.matrix_parent_inverse = Matrix.Identity(4)
    obj.matrix_basis = parent_world.inverted() @ world_matrix
    bpy.context.view_layer.update()


_EYE_FRAMES = {}


def sclera_with_lid_shading(base, side, centre, ap, forward, up, strength=None, start=None):
    """Per-eye copy of the sclera material that darkens softly toward the lid margins.

    The lids and lashes hide part of the sky of ambient light from the sclera next to them,
    so in photographs the white darkens toward the margins. The shading is head-fixed (it does
    not rotate with the globe): it uses the coordinates of an empty sitting at the eye centre,
    aligned with the face, and an ellipse fitted to the measured lid opening."""
    right = up.cross(forward).normalized()
    frame = _EYE_FRAMES.get(side)
    if frame is None:
        frame = bpy.data.objects.new("EyeFrame." + side, None)
        frame.empty_display_size = 0.005
        frame.matrix_world = Matrix.Translation(centre) @ Matrix((right, up, forward)).transposed().to_4x4()
        bpy.context.scene.collection.objects.link(frame)
        _EYE_FRAMES[side] = frame
    xs = [ap.x_min + (ap.x_max - ap.x_min) * i / 32 for i in range(33)]
    spans = [ap.margins(x) for x in xs]
    x0, a = 0.5 * (ap.x_min + ap.x_max), 0.5 * (ap.x_max - ap.x_min)
    z0 = sum(0.5 * (lo + hi) for lo, hi in spans) / len(spans)
    b = max(0.5 * (hi - lo) for lo, hi in spans)

    m = base.copy()
    m.name = base.name + "." + side
    nt = m.node_tree
    bsdf = next(n for n in nt.nodes if n.type == "BSDF_PRINCIPLED")
    colour_link = bsdf.inputs["Base Color"].links[0]
    if "IrisMelanin" in nt.nodes:
        nt.nodes["IrisMelanin"].name = "IrisMelanin"      # keep the control node's name on the copy
    tc = nt.nodes.new("ShaderNodeTexCoord")
    tc.object = frame
    sep = nt.nodes.new("ShaderNodeSeparateXYZ")
    nt.links.new(tc.outputs["Object"], sep.inputs[0])

    def math_node(op, a_in, b_in=None):
        n = nt.nodes.new("ShaderNodeMath")
        n.operation = op
        for idx, val in enumerate((a_in, b_in)):
            if val is None:
                continue
            if hasattr(val, "is_output"):
                nt.links.new(val, n.inputs[idx])
            else:
                n.inputs[idx].default_value = val
        return n.outputs[0]

    ex = math_node("DIVIDE", math_node("SUBTRACT", sep.outputs["X"], x0), a)
    ez = math_node("DIVIDE", math_node("SUBTRACT", sep.outputs["Y"], z0), b)
    rad = math_node("SQRT", math_node("ADD", math_node("MULTIPLY", ex, ex), math_node("MULTIPLY", ez, ez)))
    ramp = nt.nodes.new("ShaderNodeMapRange")
    ramp.interpolation_type = "SMOOTHSTEP"
    ramp.inputs["From Min"].default_value = LID_SHADE_START if start is None else start
    ramp.inputs["From Max"].default_value = 1.05
    ramp.inputs["To Min"].default_value = 1.0
    ramp.inputs["To Max"].default_value = 1.0 - (LID_SHADE_STRENGTH if strength is None else strength)
    nt.links.new(rad, ramp.inputs["Value"])
    mul = nt.nodes.new("ShaderNodeMix")
    mul.data_type = "RGBA"
    mul.blend_type = "MULTIPLY"
    mul.inputs[0].default_value = 1.0
    nt.links.new(colour_link.from_socket, mul.inputs[6])
    comb = nt.nodes.new("ShaderNodeCombineColor")
    for i in range(3):
        nt.links.new(ramp.outputs["Result"], comb.inputs[i])
    nt.links.new(comb.outputs[0], mul.inputs[7])
    nt.links.new(mul.outputs[2], bsdf.inputs["Base Color"])
    return m


def add_pupil_dilation_key(me, z_pupil):
    """Shape key "pupil_dilate": value 0 = PUPIL_RADIUS, 1 = PUPIL_RADIUS_MAX. The pupil disc
    scales and the iris tissue between pupil and limbus compresses radially (UVs stay put, so
    the iris pattern compresses with it, as the real stroma does)."""
    ob_tmp = bpy.data.objects.new("_tmp_" + me.name, me)
    bpy.context.scene.collection.objects.link(ob_tmp)
    ob_tmp.shape_key_add(name="Basis")
    key = ob_tmp.shape_key_add(name="pupil_dilate", from_mix=False)
    key.slider_min = (PUPIL_RADIUS_MIN - PUPIL_RADIUS) / (PUPIL_RADIUS_MAX - PUPIL_RADIUS) - 1e-6
    rp, rmax, ri = PUPIL_RADIUS, PUPIL_RADIUS_MAX, IRIS_RADIUS
    for i, v in enumerate(me.vertices):
        x, y, z = v.co
        rho = math.hypot(x, y)
        if z < z_pupil - 1e-7 or rho > ri + 1e-7 or rho < 1e-12:
            continue
        if rho <= rp + 1e-9:
            new = rho * rmax / rp
        else:
            new = rmax + (rho - rp) * (ri - rmax) / (ri - rp)
        key.data[i].co = (x * new / rho, y * new / rho, z)
    bpy.data.objects.remove(ob_tmp)


def build_eyes(rig, centres, forward, up, mats, apertures=None):
    inner_p, shell_p, z_pupil, apex = eye_profiles()
    right_img = up.cross(forward).normalized()
    # local +Z -> F (optical axis), local +Y -> U, local +X -> U x F (image-right)
    basis = Matrix((right_img, up, forward)).transposed().to_4x4()

    # Re-seat the eye bones: head exactly at the eyeball centre, Y axis along F.
    bpy.context.view_layer.objects.active = rig
    bpy.ops.object.mode_set(mode="EDIT")
    inv = rig.matrix_world.inverted()
    for side in ("L", "R"):
        eb = rig.data.edit_bones["eye." + side]
        eb.use_connect = False
        eb.head = inv @ centres[side]
        eb.tail = inv @ (centres[side] + forward * 0.03)
        eb.align_roll(inv.to_3x3() @ up)
    bpy.ops.object.mode_set(mode="OBJECT")

    def mat_index(tag_a, tag_b):
        tag = tag_b if tag_a == tag_b else (tag_a if tag_a in ("pupil",) and tag_b == "pupil" else tag_b)
        return {"pupil": 0, "iris": 1, "sclera": 2}.get(tag, 0)

    for side in ("L", "R"):
        world = Matrix.Translation(centres[side]) @ basis
        me = revolve("Eyeball." + side, inner_p, EYE_SEGMENTS, eye_uv, mat_index)
        add_pupil_dilation_key(me, z_pupil)
        ob = bpy.data.objects.new("Eyeball." + side, me)
        bpy.context.scene.collection.objects.link(ob)
        for key in ("pupil", "iris", "sclera"):
            if key == "sclera" and apertures is not None:
                me.materials.append(sclera_with_lid_shading(mats["sclera"], side, centres[side],
                                                            apertures[side], forward, up))
            elif key == "iris" and apertures is not None:
                # the upper iris sits in the shadow of the lid and lashes, as in photographs
                me.materials.append(sclera_with_lid_shading(mats["iris"], side, centres[side],
                                                            apertures[side], forward, up,
                                                            strength=IRIS_LID_SHADE, start=0.30))
            else:
                me.materials.append(mats[key])
        bone_parent(ob, rig, "eye." + side, world)

        me = revolve("Cornea." + side, shell_p, EYE_SEGMENTS, eye_uv,
                     lambda a, b: 0 if b == "cornea" else 1)
        ob = bpy.data.objects.new("Cornea." + side, me)
        bpy.context.scene.collection.objects.link(ob)
        me.materials.append(mats["cornea"])
        me.materials.append(mats["sclera_film"])
        bone_parent(ob, rig, "eye." + side, world)
        ob.visible_shadow = False
    return z_pupil, apex


# --------------------------------------------------------------------------- #
# Skin
# --------------------------------------------------------------------------- #
def make_skin_material(human, up=None):
    albedo_name = "skin_albedo.png" if os.path.exists(os.path.join(TEX, "skin_albedo.png")) \
        else "skin_albedo_base_makehuman.png"
    m = bpy.data.materials.new("Skin")
    nt, out = nodes_reset(m)
    tex = nt.nodes.new("ShaderNodeTexImage"); tex.image = image(albedo_name); tex.location = (-700, 100)
    b = nt.nodes.new("ShaderNodeBsdfPrincipled"); b.location = (200, 0)
    nt.links.new(tex.outputs["Color"], b.inputs["Base Color"])
    b.inputs["Subsurface Weight"].default_value = SKIN_SSS_WEIGHT
    b.inputs["Subsurface Radius"].default_value = SKIN_SSS_RADIUS
    b.inputs["Subsurface Scale"].default_value = SKIN_SSS_SCALE
    b.inputs["Roughness"].default_value = 0.45
    # thin eyelid skin: more translucent, slightly rosy, finer texture
    lid = nt.nodes.new("ShaderNodeAttribute"); lid.location = (-1100, 400)
    lid.attribute_type = "GEOMETRY"; lid.attribute_name = "eyelid"
    sss = nt.nodes.new("ShaderNodeMath"); sss.operation = "MULTIPLY_ADD"; sss.location = (-300, 300)
    nt.links.new(lid.outputs["Fac"], sss.inputs[0])
    sss.inputs[1].default_value = SKIN_SSS_SCALE * EYELID_SSS_GAIN
    sss.inputs[2].default_value = SKIN_SSS_SCALE
    nt.links.new(sss.outputs[0], b.inputs["Subsurface Scale"])
    tintf = nt.nodes.new("ShaderNodeMath"); tintf.operation = "MULTIPLY"; tintf.location = (-500, 350)
    nt.links.new(lid.outputs["Fac"], tintf.inputs[0])
    tintf.inputs[1].default_value = EYELID_TINT_MIX
    tint = nt.nodes.new("ShaderNodeMix"); tint.data_type = "RGBA"; tint.blend_type = "MULTIPLY"
    tint.location = (-250, 150)
    nt.links.new(tintf.outputs[0], tint.inputs[0])
    nt.links.new(tex.outputs["Color"], tint.inputs[6])
    tint.inputs[7].default_value = EYELID_TINT + (1.0,)
    nt.links.new(tint.outputs[2], b.inputs["Base Color"])
    b.inputs["Specular IOR Level"].default_value = 0.5

    rough_path = os.path.join(TEX, "skin_roughness.png")
    if os.path.exists(rough_path):
        rt = nt.nodes.new("ShaderNodeTexImage"); rt.image = image("skin_roughness.png", "Non-Color"); rt.location = (-700, -200)
        nt.links.new(rt.outputs["Color"], b.inputs["Roughness"])

    # Micro detail: pores from procedural noise + optional normal map. The noise is placed with
    # the undeformed ("Generated") coordinates, in metres, so pores travel and stretch with the
    # skin when the lids move instead of swimming through it.
    human.data.use_auto_texspace = False
    human.data.texspace_location = (0.0, 0.0, 0.0)
    human.data.texspace_size = (1.0, 1.0, 1.0)            # Generated = (local + 1) / 2
    tcg = nt.nodes.new("ShaderNodeTexCoord"); tcg.location = (-1300, -500)
    tc_map = nt.nodes.new("ShaderNodeMapping"); tc_map.location = (-1100, -500)
    tc_map.inputs["Location"].default_value = (-1.0, -1.0, -1.0)
    tc_map.inputs["Scale"].default_value = (2.0, 2.0, 2.0)
    nt.links.new(tcg.outputs["Generated"], tc_map.inputs["Vector"])
    # The model has no skin hidden inside the lid fold, so a closing lid stretches its skin
    # ~2.5x where a real lid unfolds new skin. During a blink (object property "blink", set by
    # eyes.py) the fine detail therefore follows the deformed surface instead (natural pore
    # size on the closed lid, no streaks). Open eyes (blink = 0): pores stick to the skin.
    blink_attr = nt.nodes.new("ShaderNodeAttribute"); blink_attr.location = (-1300, -300)
    blink_attr.attribute_type = "OBJECT"; blink_attr.attribute_name = "blink"
    tc_mix = nt.nodes.new("ShaderNodeMix"); tc_mix.data_type = "VECTOR"; tc_mix.location = (-900, -500)
    nt.links.new(blink_attr.outputs["Fac"], tc_mix.inputs[0])
    nt.links.new(tc_map.outputs["Vector"], tc_mix.inputs[4])
    nt.links.new(tcg.outputs["Object"], tc_mix.inputs[5])
    human["blink"] = 0.0

    class _TC:                                             # stands in for the old Object output
        outputs = {"Object": tc_mix.outputs[1]}
    tc = _TC()
    pores = nt.nodes.new("ShaderNodeTexVoronoi"); pores.location = (-700, -500)
    pores.inputs["Scale"].default_value = 2600.0
    fine = nt.nodes.new("ShaderNodeTexNoise"); fine.location = (-700, -800)
    fine.inputs["Scale"].default_value = 900.0
    fine.inputs["Detail"].default_value = 6.0
    nt.links.new(tc.outputs["Object"], pores.inputs["Vector"])
    nt.links.new(tc.outputs["Object"], fine.inputs["Vector"])
    bump1 = nt.nodes.new("ShaderNodeBump"); bump1.location = (-300, -500)
    bump1.inputs["Distance"].default_value = SKIN_PORE_DEPTH
    pore_k = nt.nodes.new("ShaderNodeMath"); pore_k.operation = "MULTIPLY_ADD"; pore_k.location = (-500, -350)
    nt.links.new(lid.outputs["Fac"], pore_k.inputs[0])
    pore_k.inputs[1].default_value = -SKIN_PORE_STRENGTH * EYELID_PORE_CUT
    pore_k.inputs[2].default_value = SKIN_PORE_STRENGTH
    pore_out = pore_k.outputs[0]
    if os.path.exists(rough_path):
        # larger, more visible pores in the oily T-zone (nose, forehead), which the baked
        # roughness map marks with its lower values
        tz = nt.nodes.new("ShaderNodeMapRange"); tz.location = (-500, -200)
        tz.inputs["From Min"].default_value = 0.50
        tz.inputs["From Max"].default_value = 0.36
        tz.inputs["To Min"].default_value = 1.0
        tz.inputs["To Max"].default_value = SKIN_PORE_TZONE_GAIN
        nt.links.new(rt.outputs["Color"], tz.inputs["Value"])
        pk = nt.nodes.new("ShaderNodeMath"); pk.operation = "MULTIPLY"; pk.location = (-350, -300)
        nt.links.new(pore_out, pk.inputs[0])
        nt.links.new(tz.outputs["Result"], pk.inputs[1])
        pore_out = pk.outputs[0]
    nt.links.new(pore_out, bump1.inputs["Strength"])
    # Pores are small, round, soft-edged pits with smooth skin between them. (Feeding the raw
    # Voronoi distance in as height tiled the whole skin with faceted cones whose ridges caught
    # the light cell by cell: a "biological cells" look.) Each cell gets a random depth and
    # about a third of the cells get no visible pore, so nothing reads as repeated.
    pit = nt.nodes.new("ShaderNodeMapRange"); pit.location = (-500, -650)
    pit.interpolation_type = "SMOOTHSTEP"
    pit.inputs["From Min"].default_value = 0.0
    pit.inputs["From Max"].default_value = SKIN_PORE_RADIUS
    pit.inputs["To Min"].default_value = 1.0
    pit.inputs["To Max"].default_value = 0.0
    nt.links.new(pores.outputs["Distance"], pit.inputs["Value"])
    cell = nt.nodes.new("ShaderNodeSeparateColor"); cell.location = (-500, -800)
    nt.links.new(pores.outputs["Color"], cell.inputs[0])
    depth = nt.nodes.new("ShaderNodeMapRange"); depth.location = (-350, -800)
    depth.inputs["To Min"].default_value = 0.35
    depth.inputs["To Max"].default_value = 1.0
    nt.links.new(cell.outputs[0], depth.inputs["Value"])
    present = nt.nodes.new("ShaderNodeMath"); present.operation = "GREATER_THAN"; present.location = (-350, -950)
    present.inputs[1].default_value = SKIN_PORE_EMPTY
    nt.links.new(cell.outputs[1], present.inputs[0])
    pit_d = nt.nodes.new("ShaderNodeMath"); pit_d.operation = "MULTIPLY"; pit_d.location = (-200, -700)
    nt.links.new(pit.outputs["Result"], pit_d.inputs[0])
    nt.links.new(depth.outputs["Result"], pit_d.inputs[1])
    pit_h = nt.nodes.new("ShaderNodeMath"); pit_h.operation = "MULTIPLY"; pit_h.location = (-100, -800)
    nt.links.new(pit_d.outputs[0], pit_h.inputs[0])
    nt.links.new(present.outputs[0], pit_h.inputs[1])
    neg = nt.nodes.new("ShaderNodeMath"); neg.operation = "MULTIPLY"; neg.location = (0, -800)
    neg.inputs[1].default_value = -1.0                     # pits go into the skin
    nt.links.new(pit_h.outputs[0], neg.inputs[0])
    nt.links.new(neg.outputs[0], bump1.inputs["Height"])
    # a pore reads mostly as a tiny, slightly darker opening (its cavity is shadowed), not as
    # relief: darken the colour a little inside each pit
    pore_col_k = nt.nodes.new("ShaderNodeMath"); pore_col_k.operation = "MULTIPLY"; pore_col_k.location = (0, -650)
    pore_col_k.inputs[1].default_value = SKIN_PORE_DARKEN
    nt.links.new(pit_h.outputs[0], pore_col_k.inputs[0])
    pore_col = nt.nodes.new("ShaderNodeMix"); pore_col.data_type = "RGBA"; pore_col.blend_type = "MULTIPLY"
    pore_col.location = (50, 150)
    nt.links.new(pore_col_k.outputs[0], pore_col.inputs[0])
    nt.links.new(tint.outputs[2], pore_col.inputs[6])
    pore_col.inputs[7].default_value = (0.80, 0.68, 0.64, 1.0)
    nt.links.new(pore_col.outputs[2], b.inputs["Base Color"])
    # soft breakup of the sheen: real skin never shines evenly
    if os.path.exists(rough_path):
        rn = nt.nodes.new("ShaderNodeTexNoise"); rn.location = (-700, -350)
        rn.inputs["Scale"].default_value = 300.0
        rn.inputs["Detail"].default_value = 4.0
        nt.links.new(tc.outputs["Object"], rn.inputs["Vector"])
        rmap = nt.nodes.new("ShaderNodeMapRange"); rmap.location = (-500, -350)
        rmap.inputs["From Min"].default_value = 0.3
        rmap.inputs["From Max"].default_value = 0.7
        rmap.inputs["To Min"].default_value = SKIN_ROUGHNESS_GAIN * (1.0 - SKIN_SHEEN_BREAKUP)
        rmap.inputs["To Max"].default_value = SKIN_ROUGHNESS_GAIN * (1.0 + SKIN_SHEEN_BREAKUP)
        nt.links.new(rn.outputs["Fac"], rmap.inputs["Value"])
        rmul = nt.nodes.new("ShaderNodeMath"); rmul.operation = "MULTIPLY"; rmul.use_clamp = True; rmul.location = (-300, -250)
        nt.links.new(rt.outputs["Color"], rmul.inputs[0])
        nt.links.new(rmap.outputs["Result"], rmul.inputs[1])
        nt.links.new(rmul.outputs[0], b.inputs["Roughness"])
    bump2 = nt.nodes.new("ShaderNodeBump"); bump2.location = (-50, -500)
    bump2.inputs["Strength"].default_value = SKIN_MICRO_RELIEF
    bump2.inputs["Distance"].default_value = 0.0002
    nt.links.new(fine.outputs["Fac"], bump2.inputs["Height"])
    nt.links.new(bump1.outputs["Normal"], bump2.inputs["Normal"])
    normal_path = os.path.join(TEX, "skin_normal.png")
    if os.path.exists(normal_path):
        ntex = nt.nodes.new("ShaderNodeTexImage"); ntex.image = image("skin_normal.png", "Non-Color"); ntex.location = (-900, -1100)
        nm = nt.nodes.new("ShaderNodeNormalMap"); nm.location = (-550, -1100)
        nmk = nt.nodes.new("ShaderNodeMath"); nmk.operation = "MULTIPLY_ADD"; nmk.location = (-750, -1250)
        nt.links.new(lid.outputs["Fac"], nmk.inputs[0])
        nmk.inputs[1].default_value = -EYELID_NORMAL_CUT
        nmk.inputs[2].default_value = 1.0
        nt.links.new(nmk.outputs[0], nm.inputs["Strength"])
        nt.links.new(ntex.outputs["Color"], nm.inputs["Color"])
        nt.links.new(nm.outputs["Normal"], bump1.inputs["Normal"])
    # thin lid skin: fine horizontal crepe lines, in undeformed coordinates so they spread
    # apart (the skin unfolds) as the closing lid stretches
    up_local = (human.matrix_world.inverted().to_3x3() @ (up if up is not None else Vector((0, 0, 1)))).normalized()
    axis = max(range(3), key=lambda i: abs(up_local[i]))
    crepe_map = nt.nodes.new("ShaderNodeMapping"); crepe_map.location = (-900, -1400)
    sc = [1.0 / (EYELID_CREPE_PERIOD * 9.0)] * 3
    sc[axis] = 1.0 / EYELID_CREPE_PERIOD
    crepe_map.inputs["Scale"].default_value = sc
    nt.links.new(tc.outputs["Object"], crepe_map.inputs["Vector"])
    crepe = nt.nodes.new("ShaderNodeTexNoise"); crepe.location = (-700, -1400)
    crepe.inputs["Scale"].default_value = 1.0
    crepe.inputs["Detail"].default_value = 3.0
    crepe.inputs["Roughness"].default_value = 0.55
    nt.links.new(crepe_map.outputs["Vector"], crepe.inputs["Vector"])
    crepe_k = nt.nodes.new("ShaderNodeMath"); crepe_k.operation = "MULTIPLY"; crepe_k.location = (-500, -1250)
    nt.links.new(lid.outputs["Fac"], crepe_k.inputs[0])
    crepe_k.inputs[1].default_value = EYELID_CREPE
    bump3 = nt.nodes.new("ShaderNodeBump"); bump3.location = (100, -700)
    bump3.inputs["Distance"].default_value = 0.00005
    nt.links.new(crepe_k.outputs[0], bump3.inputs["Strength"])
    nt.links.new(crepe.outputs["Fac"], bump3.inputs["Height"])
    nt.links.new(bump2.outputs["Normal"], bump3.inputs["Normal"])
    nt.links.new(bump3.outputs["Normal"], b.inputs["Normal"])
    nt.links.new(b.outputs["BSDF"], out.inputs["Surface"])

    human.data.materials.clear()
    human.data.materials.append(m)
    for p in human.data.polygons:
        p.use_smooth = True
    return m


# --------------------------------------------------------------------------- #
# Camera, lights, render settings
# --------------------------------------------------------------------------- #
def look_at_matrix(location, target, up):
    z = (location - target).normalized()          # camera looks along -Z
    x = up.cross(z).normalized()
    y = z.cross(x).normalized()
    m = Matrix((x, y, z)).transposed().to_4x4()
    m.translation = location
    return m


def build_camera_and_lights(mid, forward, up):
    scene = bpy.context.scene
    right = up.cross(forward).normalized()

    cam_data = bpy.data.cameras.new("RenderCam")
    cam_data.lens = FOCAL_LENGTH_MM
    cam_data.sensor_width = SENSOR_MM
    cam_data.sensor_fit = "HORIZONTAL"
    cam_data.clip_start = 0.05
    cam_data.clip_end = 10.0
    cam = bpy.data.objects.new("RenderCam", cam_data)
    scene.collection.objects.link(cam)
    cam.matrix_world = look_at_matrix(mid + forward * CAMERA_DISTANCE_M, mid, up)
    cam.lock_location = cam.lock_rotation = cam.lock_scale = (True, True, True)
    scene.camera = cam

    tgt = bpy.data.objects.new("GazeTarget", None)
    tgt.empty_display_type = "SPHERE"
    tgt.empty_display_size = 0.005
    tgt.location = mid + forward * FIXATION_DISTANCE_M
    tgt.hide_render = True
    scene.collection.objects.link(tgt)

    def area(name, offset, size, power, color=(1, 1, 1)):
        ld = bpy.data.lights.new(name, "AREA")
        ld.shape = "RECTANGLE"
        ld.size = size[0]
        ld.size_y = size[1]
        ld.energy = power
        ld.color = color
        ob = bpy.data.objects.new(name, ld)
        scene.collection.objects.link(ob)
        loc = mid + forward * offset[0] + right * offset[1] + up * offset[2]
        ob.matrix_world = look_at_matrix(loc, mid, up)
        return ob

    # offsets = (forward, image-right, up) in metres from the eye midpoint
    # Key and fill sit > 55 deg off the camera axis so their corneal reflections land on the
    # iris, well clear of the pupil, for every gaze in the +/-5 cm range.
    area("Key", (0.48, -0.75, 0.35), (0.26, 0.35), KEY_WATTS, (1.0, 0.97, 0.94))
    area("Fill", (0.40, 0.88, -0.12), (0.48, 0.48), FILL_WATTS, (0.93, 0.96, 1.0))
    area("Rim", (-0.50, 0.65, 0.55), (0.40, 0.60), RIM_WATTS)

    world = bpy.data.worlds.new("Studio")
    world.use_nodes = True
    bg = world.node_tree.nodes["Background"]
    bg.inputs["Color"].default_value = (0.10, 0.105, 0.11, 1.0)
    bg.inputs["Strength"].default_value = 1.0
    if STUDIO_ENVIRONMENT:
        # soft studio surroundings: brighter ceiling, darker floor, a faint horizon band. Seen
        # mostly in the cornea's reflection and as gentle ambient fill; identical every frame.
        nt = world.node_tree
        tc = nt.nodes.new("ShaderNodeTexCoord")
        sep = nt.nodes.new("ShaderNodeSeparateXYZ")
        nt.links.new(tc.outputs["Generated"], sep.inputs[0])
        dot = nt.nodes.new("ShaderNodeVectorMath")
        dot.operation = "DOT_PRODUCT"
        nt.links.new(tc.outputs["Generated"], dot.inputs[0])
        dot.inputs[1].default_value = tuple(up)
        ramp = nt.nodes.new("ShaderNodeValToRGB")
        ramp.color_ramp.interpolation = "EASE"
        el = ramp.color_ramp.elements
        g = AMBIENT_GAIN
        el[0].position, el[0].color = 0.0, (0.035 * g, 0.034 * g, 0.033 * g, 1.0)
        el[1].position, el[1].color = 1.0, (0.34 * g, 0.335 * g, 0.33 * g, 1.0)
        mid_el = el.new(0.52)
        mid_el.color = (0.13 * g, 0.13 * g, 0.13 * g, 1.0)
        mapr = nt.nodes.new("ShaderNodeMapRange")
        mapr.inputs["From Min"].default_value = -1.0
        mapr.inputs["From Max"].default_value = 1.0
        nt.links.new(dot.outputs["Value"], mapr.inputs["Value"])
        nt.links.new(mapr.outputs["Result"], ramp.inputs["Fac"])
        nt.links.new(ramp.outputs["Color"], bg.inputs["Color"])
    scene.world = world
    return cam, tgt


def configure_render():
    scene = bpy.context.scene
    r = scene.render
    r.engine = "CYCLES"
    r.resolution_x = RESOLUTION
    r.resolution_y = RESOLUTION
    r.resolution_percentage = 100
    r.pixel_aspect_x = r.pixel_aspect_y = 1.0
    r.image_settings.file_format = "PNG"
    r.image_settings.color_mode = "RGB"
    r.image_settings.color_depth = "8"
    r.image_settings.compression = 30
    r.film_transparent = False
    r.use_motion_blur = False
    r.dither_intensity = 0.0          # dithering is the only stochastic post step
    r.use_stamp = False
    for attr in dir(r):               # no date / render time / file path metadata in the PNGs
        if attr.startswith("use_stamp_"):
            try:
                setattr(r, attr, False)
            except (AttributeError, TypeError):
                pass
    r.threads_mode = "AUTO"
    r.use_persistent_data = False

    c = scene.cycles
    c.samples = SAMPLES
    c.use_adaptive_sampling = False   # fixed sample count => reproducible noise pattern
    c.seed = 0
    c.use_animated_seed = False
    c.use_denoising = True
    c.denoiser = "OPENIMAGEDENOISE"
    c.denoising_input_passes = "RGB_ALBEDO_NORMAL"
    try:
        c.denoising_use_gpu = False   # CPU OIDN gives stable results across machines
    except Exception:
        pass
    c.max_bounces = 8
    c.transmission_bounces = 8
    c.transparent_max_bounces = 16
    c.caustics_reflective = False
    c.caustics_refractive = False
    c.sample_clamp_indirect = 10.0
    c.device = "CPU"

    scene.view_settings.view_transform = "Filmic"
    scene.view_settings.look = "Medium High Contrast"
    scene.view_settings.exposure = 0.0
    scene.view_settings.gamma = 1.0
    scene.display_settings.display_device = "sRGB"
    scene.frame_set(1)


# --------------------------------------------------------------------------- #
def main():
    bpy.ops.wm.read_factory_settings(use_empty=True)
    scene = bpy.context.scene
    scene.unit_settings.system = "METRIC"
    scene.unit_settings.scale_length = 1.0

    human, rig, meas, forward, up, centres, apertures = build_human()
    mats = make_eye_materials()
    z_pupil, apex = build_eyes(rig, centres, forward, up, mats, apertures)
    make_skin_material(human, up)
    # Smooth render-time subdivision for the head (after the armature). Added BEFORE the hair
    # and corner details are placed, so they sit on the final smoothed skin (subdivision pulls
    # convex skin such as the brow ridge inward by up to ~1 mm).
    sub = human.modifiers.new("Subdivision", "SUBSURF")
    sub.levels = 1
    sub.render_levels = 2
    tear_objs = build_wet_details(centres, apertures, forward, up, mats, human)
    cam_pos = (centres["L"] + centres["R"]) * 0.5 + forward * CAMERA_DISTANCE_M
    cards = [o for o in bpy.data.objects if o.type == "MESH" and "eyelash" in o.name.lower()]
    if STRAND_HAIR:
        for o in cards:
            o.hide_render = True          # replaced by individual strands
            o.hide_viewport = True
        lashes = [build_lash_strands(human, centres, apertures, forward, up, cam_pos)]
        build_brow_strands(forward, up, cam_pos)
    else:
        lashes = cards
    for o in cards:
        # The lash cards are flat alpha strips; as shadow casters they drop solid triangular
        # shadows on the sclera that real (hair-thin) lashes never would.
        o.visible_shadow = False
    # the brow card and hairs get the same field as the skin under them, so whatever little
    # the brow moves in a blink, hair and skin move together
    brows = [o for o in bpy.data.objects if o.type == "MESH" and "eyebrow" in o.name.lower()]
    brows += [o for o in bpy.data.objects if o.name == "BrowStrands"]
    add_eyelid_mask(human, centres, apertures, forward, up)
    key_names = add_lid_keys([human] + brows, lashes + tear_objs, centres, apertures, forward, up, brows)


    mid = (centres["L"] + centres["R"]) * 0.5
    cam, tgt = build_camera_and_lights(mid, forward, up)
    configure_render()

    calib = {
        "units": "metres",
        "rig": rig.name,
        "bone_L": "eye.L",
        "bone_R": "eye.R",
        "camera": cam.name,
        "target": tgt.name,
        "eye_center_L": list(centres["L"]),
        "eye_center_R": list(centres["R"]),
        "eye_midpoint": list(mid),
        "forward": list(forward),
        "up": list(up),
        "image_right": list(up.cross(forward).normalized()),
        "eye_radius": EYE_RADIUS,
        "iris_radius": IRIS_RADIUS,
        "pupil_radius": PUPIL_RADIUS,
        "pupil_radius_max": PUPIL_RADIUS_MAX,
        "pupil_radius_min": PUPIL_RADIUS_MIN,
        "pupil_offset_L": z_pupil,
        "pupil_offset_R": z_pupil,
        "cornea_apex_offset": apex,
        "cornea_radius": CORNEA_CURVATURE,
        "cornea_center_offset": cornea_geometry()[2],
        "shell_radius": cornea_geometry()[0],
        "cornea_ior": CORNEA_IOR,
        "lights": ["Key", "Fill", "Rim"],
        "limbus_offset": math.sqrt(EYE_RADIUS ** 2 - IRIS_RADIUS ** 2),
        "aperture_L": aperture_samples(apertures["L"]),
        "aperture_R": aperture_samples(apertures["R"]),
        "fixation_distance": FIXATION_DISTANCE_M,
        "camera_distance": CAMERA_DISTANCE_M,
        "focal_length_mm": FOCAL_LENGTH_MM,
        "sensor_width_mm": SENSOR_MM,
        "ipd": (centres["L"] - centres["R"]).length,
        "lid_follow": {
            "objects": [human.name] + [o.name for o in lashes + tear_objs],
            "up_key": "lid_gaze_up",
            "down_key": "lid_gaze_down",
            "blink_keys": [k for k in key_names if k.startswith("lid_blink")],
        },
    }
    scene["xr_calib"] = json.dumps(calib)
    log("IPD %.4f m, eye diameter %.4f m, midpoint %s" % (calib["ipd"], 2 * EYE_RADIUS, tuple(round(c, 4) for c in mid)))

    # Start in the reset pose: both eyes converged on the fixation target.
    sys.path.insert(0, os.path.join(ROOT, "wrapper"))
    import eyes
    eyes.reset()

    enable_clothes_masks()
    bpy.ops.file.pack_all()
    bpy.ops.wm.save_as_mainfile(filepath=OUT_BLEND, compress=True)
    log("saved", OUT_BLEND)


if __name__ == "__main__":
    main()
